const LEAVE_TIMES_KEY='uk.co.crosscountry.shiftapp.leaveScheduledTimes.v1';
function getLeaveScheduledTimes(){try{return JSON.parse(localStorage.getItem(LEAVE_TIMES_KEY)||'{}')}catch{return {}}}
let leaveScheduledTimes=getLeaveScheduledTimes();
const SB_HOURS_KEY='uk.co.crosscountry.shiftapp.safetyBriefHours.v1';
