function getSpareTermLength(){const value=localStorage.getItem(SPARE_TERM_LENGTH_KEY)||DEFAULT_SPARE_TERM_LENGTH;return /^([01]\d|2[0-3]):[0-5]\d$/.test(value)?value:DEFAULT_SPARE_TERM_LENGTH}
function spareTermHours(){const [h,m]=getSpareTermLength().split(':').map(Number);return h+m/60}
const DEFAULT_ANNUAL_BASIC_SALARY=42778.51;
