function getAnnualBasicSalary(){const value=Number(localStorage.getItem(ANNUAL_BASIC_SALARY_KEY));return Number.isFinite(value)&&value>=0?value:DEFAULT_ANNUAL_BASIC_SALARY;}
function getPayRates(){try{return {...DEFAULT_PAY_RATES,...JSON.parse(localStorage.getItem(PAY_RATE_KEY)||'{}')}}catch{return {...DEFAULT_PAY_RATES}}}
function getCommissionRates(){try{return {...DEFAULT_COMMISSION_RATES,...JSON.parse(localStorage.getItem(COMMISSION_RATE_KEY)||'{}')}}catch{return {...DEFAULT_COMMISSION_RATES}}}
