const state={trains:[],entries:[],diversionRoutes:[...DEFAULT_DIVERSION_ROUTES],archivedShifts:[]};
let editingTrainIndex=null, editingEntryIndex=null, editingIncidentUpdateIndex=null, editingIncidentUpdateParentIndex=null, archiveViewEntries=[];
let archiveEditingRecord=null, archiveActiveState=null, archiveRecordBackup=null, selectedArchiveRecordId='', selectedArchiveEntryActionIndex=-1;
let archiveCalendarMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);
let selectedArchiveDate='';
let ticketCustomOperator='', ticketCustomReason='', ticketCustomTarget='';
let originalShiftHours=null;
const nowLocal=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)};
const stamp=()=>new Date().toISOString();
function archiveTimestamp(reference){const now=new Date(),base=String(reference||'').slice(0,10);if(/^\d{4}-\d{2}-\d{2}$/.test(base)){const time=[now.getHours(),now.getMinutes(),now.getSeconds()].map(v=>String(v).padStart(2,'0'));return new Date(`${base}T${time.join(':')}`).toISOString()}return stamp()}
const fmt=iso=>{const d=new Date(iso);return Number.isNaN(d.getTime())?'Unknown time':d.toLocaleString('en-GB',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'})};
const cleanHead=v=>String(v||'').toUpperCase().replace(/[^0-9A-Z]/g,'').slice(0,4);
const needsUnit=activity=>!/(PASS|TAXI)/i.test(String(activity||''));
const unitText=t=>needsUnit(t.from)?`Unit ${esc(t.unit||'Not recorded')}${t.unit2?' + '+esc(t.unit2):''}`:'';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const status=msg=>{$('status').textContent=msg};
let confirmResolver=null;
function customConfirm({title='Please confirm',message='Are you sure?',accept='Confirm',danger=true}={}){return new Promise(resolve=>{confirmResolver=resolve;$('confirmTitle').textContent=title;$('confirmMessage').textContent=message;$('confirmAccept').textContent=accept;$('confirmAccept').className=danger?'danger':'primary';$('confirmDialog').showModal();$('confirmCancel').focus()})}
function finishConfirm(value){if(!$('confirmDialog').open)return;$('confirmDialog').close();const done=confirmResolver;confirmResolver=null;if(done)done(value)}
$('confirmAccept').addEventListener('click',()=>finishConfirm(true));$('confirmCancel').addEventListener('click',()=>finishConfirm(false));$('confirmClose').addEventListener('click',()=>finishConfirm(false));$('confirmDialog').addEventListener('cancel',e=>{e.preventDefault();finishConfirm(false)});
let delayClassificationResolver=null;
function chooseDelayClassification(){return new Promise(resolve=>{delayClassificationResolver=resolve;$('delayClassificationDialog').showModal();$('delayClassificationDialog').querySelector('[data-delay-classification="NEW"]').focus()})}
function finishDelayClassification(value){const dlg=$('delayClassificationDialog');if(dlg.open)dlg.close();const done=delayClassificationResolver;delayClassificationResolver=null;if(done)done(value)}
document.querySelectorAll('[data-delay-classification]').forEach(button=>button.addEventListener('click',()=>finishDelayClassification(button.dataset.delayClassification)));
$('delayClassificationCancel').addEventListener('click',()=>finishDelayClassification(null));$('delayClassificationClose').addEventListener('click',()=>finishDelayClassification(null));$('delayClassificationDialog').addEventListener('cancel',e=>{e.preventDefault();finishDelayClassification(null)});
// Live CrossCountry clock: Europe/London handles GMT/BST transitions automatically.
function ledDigits(value){
 return String(value).split('').map(n=>'<span class="led-digit">'+n+'</span>').join('');
}
function updateClock(){
 const now=new Date(), parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(now);
 const part=type=>parts.find(x=>x.type===type)?.value||'00';
 $('clockHours').innerHTML=ledDigits(part('hour'));$('clockMinutes').innerHTML=ledDigits(part('minute'));const seconds=Number(part('second'));$('clockSeconds').innerHTML=ledDigits(String(seconds).padStart(2,'0'));$('clockSeconds').classList.remove('seconds-red','seconds-orange','seconds-green');$('clockSeconds').classList.add(seconds<=10?'seconds-red':seconds<=19?'seconds-orange':'seconds-green');
 $('clockDate').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(now).toUpperCase();
 const zone=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',timeZoneName:'short'}).formatToParts(now).find(x=>x.type==='timeZoneName')?.value||'UK TIME';
 $('clockZone').textContent=zone;
}
updateClock();window.setInterval(updateClock,250);
$('shiftDate').value=nowLocal();
if($('version'))$('version').textContent='v'+VERSION;
function currentShiftSnapshot(){return {appId:APP_ID,version:VERSION,commissionRates:getCommissionRates(),payRates:getPayRates(),annualBasicSalary:getAnnualBasicSalary(),spareTermLength:getSpareTermLength(),shift:{date:$('shiftDate').value,jobNumber:$('shiftJobNumber').value.trim(),bookOn:$('bookOn').value,bookOff:$('bookOff').value,originalShiftHours,notes:$('shiftNotes').value,rdw:$('shiftIsRDW').checked},trains:state.trains,entries:state.entries,diversionRoutes:state.diversionRoutes,calendarCodes,leaveScheduledTimes,safetyBriefHours,updatedAt:stamp()}}
function snapshot(){return {...currentShiftSnapshot(),archivedShifts:state.archivedShifts}}
function hasCurrentShiftData(s=currentShiftSnapshot()){return !!(s.shift?.jobNumber||s.shift?.bookOn||s.shift?.bookOff||s.shift?.notes||s.trains?.length||s.entries?.length)}
function archiveRecord(s,reason='manual'){const copy=JSON.parse(JSON.stringify(s));return {...copy,archiveId:(crypto.randomUUID?crypto.randomUUID():String(Date.now())+'-'+Math.random().toString(16).slice(2)),archivedAt:stamp(),archiveReason:reason}}
function shiftContentKey(s){return JSON.stringify({shift:s?.shift||{},trains:s?.trains||[],entries:s?.entries||[],diversionRoutes:s?.diversionRoutes||[]})}
function hasArchivedCopyOf(s,excludeArchiveId=''){const key=shiftContentKey(s);return state.archivedShifts.some(item=>item.archiveId!==excludeArchiveId&&shiftContentKey(item)===key)}
function applyCurrentShift(s){if(/^([01]\d|2[0-3]):[0-5]\d$/.test(String(s.spareTermLength||'')))localStorage.setItem(SPARE_TERM_LENGTH_KEY,s.spareTermLength);if(Number.isFinite(Number(s.annualBasicSalary))&&Number(s.annualBasicSalary)>=0)localStorage.setItem(ANNUAL_BASIC_SALARY_KEY,String(Number(s.annualBasicSalary)));if(s.calendarCodes&&typeof s.calendarCodes==='object'){calendarCodes=s.calendarCodes;localStorage.setItem(CALENDAR_CODES_KEY,JSON.stringify(calendarCodes))}if(s.leaveScheduledTimes&&typeof s.leaveScheduledTimes==='object'){leaveScheduledTimes=s.leaveScheduledTimes;localStorage.setItem(LEAVE_TIMES_KEY,JSON.stringify(leaveScheduledTimes))}if(s.safetyBriefHours&&typeof s.safetyBriefHours==='object'){safetyBriefHours=s.safetyBriefHours;localStorage.setItem(SB_HOURS_KEY,JSON.stringify(safetyBriefHours))}if(s.payRates&&Number.isFinite(Number(s.payRates.weekday))&&Number.isFinite(Number(s.payRates.sunday)))localStorage.setItem(PAY_RATE_KEY,JSON.stringify({weekday:Number(s.payRates.weekday),sunday:Number(s.payRates.sunday)}));if(s.commissionRates&&Number.isFinite(Number(s.commissionRates.perScan))&&Number.isFinite(Number(s.commissionRates.salesPercent)))localStorage.setItem(COMMISSION_RATE_KEY,JSON.stringify({perScan:Number(s.commissionRates.perScan),salesPercent:Number(s.commissionRates.salesPercent)}));$('shiftDate').value=s.shift?.date||nowLocal();$('shiftJobNumber').value=s.shift?.jobNumber||s.shift?.headcode||'';originalShiftHours=Number.isFinite(Number(s.shift?.originalShiftHours))&&Number(s.shift?.originalShiftHours)>0?Number(s.shift.originalShiftHours):null;$('shiftNotes').value=s.shift?.notes||'';$('shiftIsRDW').checked=!!s.shift?.rdw;$('bookOn').value=s.shift?.bookOn||'';$('bookOff').value=s.shift?.bookOff||'';updateOriginalShiftHoursLine();updateShiftJobNumberStyle();updateShiftLength();state.trains=Array.isArray(s.trains)?JSON.parse(JSON.stringify(s.trains)):[];state.entries=Array.isArray(s.entries)?JSON.parse(JSON.stringify(s.entries)):[];state.entries.forEach(e=>{if(e?.type==='Passenger Counts'&&typeof e.text==='string')e.text=e.text.replace(/Applies to:/gi,'Train portion:')});state.diversionRoutes=Array.isArray(s.diversionRoutes)?[...new Set([...DEFAULT_DIVERSION_ROUTES,...s.diversionRoutes.filter(r=>r!=='Newcastle Bridges – KEB East to South Jn')])]:[...DEFAULT_DIVERSION_ROUTES]}
let driveSession='',driveTimer=null,driveBusy=false;
const DRIVE_PENDING_KEY=APP_ID+'.driveBackupPending',DRIVE_SESSION_KEY=APP_ID+'.driveSession',DRIVE_WORKER_KEY=APP_ID+'.driveWorkerUrl',DRIVE_SYNC_HOLD_KEY=APP_ID+'.driveSyncHold',DRIVE_DEVICE_READY_KEY=APP_ID+'.driveDeviceReady';
const DEFAULT_DRIVE_WORKER_URL='https://xc-shiftapp-drive-backup.vyct2r447f.workers.dev';
function workerUrl(){return String($('driveWorkerUrl')?.value||localStorage.getItem(DRIVE_WORKER_KEY)||DEFAULT_DRIVE_WORKER_URL).trim().replace(/\/$/,'')}
function driveStatus(message,badge){if($('driveBackupStatus'))$('driveBackupStatus').textContent=message;if($('driveBackupBadge'))$('driveBackupBadge').textContent=badge||'Google Drive'}
function saveDriveWorkerUrl(){const value=workerUrl();if(!value){driveStatus('Enter your deployed Cloudflare Worker URL first.','Setup needed');return false}try{const u=new URL(value);if(u.protocol!=='https:'||!u.hostname.endsWith('.workers.dev')&&!u.hostname.includes('.'))throw new Error('Use the HTTPS URL supplied by Cloudflare.');localStorage.setItem(DRIVE_WORKER_KEY,value);$('driveWorkerUrl').value=value;$('driveWorkerEditor')?.classList.add('hidden');$('driveWorkerEditToggle')?.setAttribute('aria-expanded','false');driveStatus('Secure backup service address saved. Connect Google Drive when ready.','Ready');return true}catch(e){driveStatus('Check the Cloudflare Worker URL. '+e.message,'Setup needed');return false}}
async function workerRequest(path,options={}){const base=workerUrl();if(!base)throw new Error('Add your Cloudflare Worker URL in Backup & restore settings.');const headers={'Content-Type':'application/json',...(options.headers||{})};if(driveSession)headers.Authorization='Bearer '+driveSession;const response=await fetch(base+path,{...options,headers,mode:'cors',cache:'no-store'});let data={};try{data=await response.json()}catch{}if(!response.ok){const error=new Error(data.error||('Backup service returned '+response.status));error.status=response.status;throw error}return data}
function driveConnect(){if(!saveDriveWorkerUrl())return;driveStatus('Opening secure Google authorisation…','Connecting');window.location.assign(workerUrl()+'/auth/start')}
async function performDriveBackup(force=false){if(driveBusy)return;if(!driveSession){driveStatus('Your diary is saved locally. Connect Google Drive to enable cloud backup.','Not connected');return}if(localStorage.getItem(DRIVE_SYNC_HOLD_KEY)==='1'&&!force){driveStatus('A cloud backup already exists. Import it first, or use Back up now to deliberately replace today’s cloud copy with this device’s diary.','Import required');return}if(localStorage.getItem(DRIVE_SYNC_HOLD_KEY)==='1'&&force){if(!await customConfirm({title:'Upload this device’s diary?',message:'A cloud backup already exists. Uploading now may replace today’s backup for this date with the diary on this device. Import the cloud backup first if you need to keep its latest changes. Continue?',accept:'Upload this device’s diary'}))return;localStorage.removeItem(DRIVE_SYNC_HOLD_KEY);localStorage.setItem(DRIVE_DEVICE_READY_KEY,'1')}if(!navigator.onLine){localStorage.setItem(DRIVE_PENDING_KEY,'1');driveStatus('Saved locally. Backup waiting for an internet connection.','Waiting');return}driveBusy=true;try{const result=await workerRequest('/backup',{method:'POST',body:JSON.stringify({...snapshot(),cloudBackupDate:nowLocal()})});localStorage.removeItem(DRIVE_PENDING_KEY);localStorage.setItem(DRIVE_DEVICE_READY_KEY,'1');driveStatus('Daily backup saved: '+(result.backupFileName||('XC-ShiftApp-Backup-'+(result.backupDate||nowLocal())+'.json'))+' in '+(result.folderPath||'XC ShiftApp Backups')+'. Previous days are kept.','Synced')}catch(err){localStorage.setItem(DRIVE_PENDING_KEY,'1');if(/session|authori[sz]|expired|connect/i.test(err.message)){driveSession='';localStorage.removeItem(DRIVE_SESSION_KEY);$('driveBackupNow').disabled=true;driveStatus('Google authorisation needs renewing. Select Connect Google Drive. Your diary remains saved locally.','Reconnect')}else driveStatus('Backup failed. Your diary remains safe on this device. '+err.message,'Backup failed')}finally{driveBusy=false}}
async function restoreDriveBackup(){if(!driveSession){driveStatus('Connect Google Drive on this device before importing a cloud backup.','Not connected');return}if(!navigator.onLine){driveStatus('An internet connection is required to import from Google Drive.','Offline');return}if(!await customConfirm({title:'Import diary from Google Drive?',message:'The cloud backup will replace the active diary on this device. Existing archived shifts will be kept and cloud archives will be added without duplicates. If this device has an active shift, it will first be saved into Archived Shifts. Continue?',accept:'Import from Google Drive',danger:false}))return;try{$('driveRestore').disabled=true;driveStatus('Downloading your Google Drive backup…','Restoring');const result=await workerRequest('/restore',{method:'GET'});const imported=result.backup;if(!imported||imported.appId!==APP_ID||!imported.shift||!Array.isArray(imported.entries)||!Array.isArray(imported.trains))throw new Error('The cloud file is not a valid XC ShiftApp backup.');const current=currentShiftSnapshot(),oldArchives=state.archivedShifts.slice();if(hasCurrentShiftData(current))state.archivedShifts.push(archiveRecord(current,'automatic-before-cloud-restore'));const incomingArchives=Array.isArray(imported.archivedShifts)?imported.archivedShifts:[];const known=new Set(state.archivedShifts.map(x=>x.archiveId).filter(Boolean));incomingArchives.forEach(r=>{if(!r.archiveId||!known.has(r.archiveId)){state.archivedShifts.push(r.archiveId?r:archiveRecord(r,'cloud-imported'));if(r.archiveId)known.add(r.archiveId)}});applyCurrentShift(imported);if(!persist(true)){applyCurrentShift(current);state.archivedShifts=oldArchives;render();throw new Error('Restore could not be saved on this device. Your previous diary has been reinstated.')}render();renderArchivedShifts();localStorage.removeItem(DRIVE_PENDING_KEY);localStorage.removeItem(DRIVE_SYNC_HOLD_KEY);localStorage.setItem(DRIVE_DEVICE_READY_KEY,'1');driveStatus('Cloud restore completed from '+(result.modifiedTime?new Date(result.modifiedTime).toLocaleString('en-GB'):'your latest Google Drive backup')+'.','Restored');$('archivePanel').open=true;performDriveBackup()}catch(err){driveStatus('Cloud restore failed. Your existing diary remains available. '+err.message,'Restore failed')}finally{$('driveRestore').disabled=!driveSession}}
function queueDriveBackup(){localStorage.setItem(DRIVE_PENDING_KEY,'1');if(!driveSession||localStorage.getItem(DRIVE_SYNC_HOLD_KEY)==='1')return;clearTimeout(driveTimer);driveTimer=setTimeout(()=>performDriveBackup(),1100)}
function persist(silent=false,skipCloudBackup=false){try{const active=currentShiftSnapshot();if(archiveEditingRecord){archiveEditingRecord.entries=state.entries;archiveEditingRecord.trains=state.trains;archiveEditingRecord.updatedAt=stamp();/* Keep the live diary's arrays isolated while an archived shift is being edited. */if(archiveActiveState){active.entries=archiveActiveState.entries;active.trains=archiveActiveState.trains}}const payload=JSON.stringify({...active,archivedShifts:state.archivedShifts});localStorage.setItem(STORE,payload);const verify=JSON.parse(localStorage.getItem(STORE)||'null');if(!verify||!Array.isArray(verify.archivedShifts))throw new Error('Saved diary could not be verified');if(!silent)status('Saved on this device · '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}));if(!skipCloudBackup)queueDriveBackup();return true}catch(err){console.warn('Diary save failed',err);if(!silent)status('Could not save locally. Check device storage settings.');return false}}
$('driveWorkerUrl').value=localStorage.getItem(DRIVE_WORKER_KEY)||DEFAULT_DRIVE_WORKER_URL;
$('driveWorkerEditToggle').addEventListener('click',()=>{const editor=$('driveWorkerEditor'),open=editor.classList.toggle('hidden')===false;$('driveWorkerEditToggle').setAttribute('aria-expanded',String(open));if(open)$('driveWorkerUrl').focus()});
