$('driveSettingsOpen').addEventListener('click',renderCommissionSettings);
$('driveSettingsOpen').addEventListener('click',()=>{const r=getPayRates();$('settingsWeekdayRate').value=r.weekday;$('settingsSundayRate').value=r.sunday;$('settingsSpareTermLength').value=getSpareTermLength()});
