$('driveSettingsOpen').addEventListener('click',()=>{$('settingsDistanceUnit').value=localStorage.getItem(DISTANCE_UNIT_KEY)==='km'?'km':'mi';$('distanceUnitStatus').textContent=`Mapping distances are displayed in ${$('settingsDistanceUnit').value==='mi'?'miles':'kilometres'}.`;});
$('saveDistanceUnit').addEventListener('click',()=>{const unit=$('settingsDistanceUnit').value==='km'?'km':'mi';localStorage.setItem(DISTANCE_UNIT_KEY,unit);$('distanceUnitStatus').textContent=`Saved. Mapping distances are now displayed in ${unit==='mi'?'miles':'kilometres'}.`;document.dispatchEvent(new Event('mappingdistancechange'));});
function addHistoricShiftRow(values={}){const row=document.createElement('tr');row.className='historic-shift-row';row.innerHTML=`<td><input type="date" class="historic-shift-date" aria-label="Shift date" value="${esc(values.date||'')}"></td><td><input type="text" class="historic-shift-number" aria-label="Shift number" maxlength="30" placeholder="e.g. NES0613" value="${esc(values.jobNumber||'')}"></td><td><input type="time" class="historic-shift-book-on" aria-label="Book on time" step="60" value="${esc(values.bookOn||'')}"></td><td><input type="time" class="historic-shift-book-off" aria-label="Book off time" step="60" value="${esc(values.bookOff||'')}"></td><td><button type="button" class="historic-shift-remove" aria-label="Remove row" title="Remove row">×</button></td>`;$('historicShiftRows').appendChild(row)}
