$('historicShiftSave')?.addEventListener('click',()=>{const rows=[...$('historicShiftRows').querySelectorAll('tr')],entries=rows.map((row,index)=>({row,index,date:row.querySelector('.historic-shift-date').value,jobNumber:row.querySelector('.historic-shift-number').value.trim(),bookOn:row.querySelector('.historic-shift-book-on').value,bookOff:row.querySelector('.historic-shift-book-off').value})).filter(x=>x.date||x.jobNumber||x.bookOn||x.bookOff);if(!entries.length){$('historicShiftStatus').textContent='Enter at least one previous shift first.';return}const invalid=entries.find(x=>!x.date||!x.jobNumber||!x.bookOn||!x.bookOff);if(invalid){$('historicShiftStatus').textContent=`Complete all four fields in row ${invalid.index+1} before saving.`;return}const badTime=entries.find(x=>x.bookOn===x.bookOff);if(badTime){$('historicShiftStatus').textContent=`Book on and book off must be different in row ${badTime.index+1}.`;return}const old=state.archivedShifts.slice(),created=entries.map(x=>archiveRecord({appId:APP_ID,version:VERSION,commissionRates:getCommissionRates(),payRates:getPayRates(),spareTermLength:getSpareTermLength(),shift:{date:x.date,jobNumber:x.jobNumber,bookOn:x.bookOn,bookOff:x.bookOff,originalShiftHours:null,notes:'additional historic shift entered. Shift time includes any logged overtime or delay.'},trains:[],entries:[],diversionRoutes:state.diversionRoutes},'additional-historic-shift'));state.archivedShifts.push(...created);if(!persist(true)){state.archivedShifts=old;$('historicShiftStatus').textContent='Could not save these shifts. Your existing records have been preserved; check device storage and try again.';return}const firstDate=entries.map(x=>x.date).sort()[0];selectedArchiveDate=firstDate;const [year,month]=firstDate.split('-').map(Number);archiveCalendarMonth=new Date(year,month-1,1);renderArchivedShifts();$('historicShiftStatus').textContent=`${created.length} additional historic ${created.length===1?'shift':'shifts'} saved and added to the archive calendar.`;$('historicShiftRows').innerHTML='';addHistoricShiftRow();status(`${created.length} additional historic ${created.length===1?'shift':'shifts'} saved.`)});
$('savePayRates').addEventListener('click',()=>{const weekday=Number($('settingsWeekdayRate').value),sunday=Number($('settingsSundayRate').value),spareLength=$('settingsSpareTermLength').value;if(!Number.isFinite(weekday)||weekday<0||!Number.isFinite(sunday)||sunday<0||!/^([01]\d|2[0-3]):[0-5]\d$/.test(spareLength)){$('payRatesStatus').textContent='Enter valid hourly rates and an average spare length in HH:MM format.';return}localStorage.setItem(PAY_RATE_KEY,JSON.stringify({weekday,sunday}));localStorage.setItem(SPARE_TERM_LENGTH_KEY,spareLength);$('payRatesStatus').textContent=`Saved: £${weekday.toFixed(2)}/hour Monday–Saturday, £${sunday.toFixed(2)}/hour Sunday and ${spareLength} average A/R (spare) / Safety Brief length.`;updateShiftLength();persist(true);status('Hourly pay rates updated in App Settings.')});
$('saveCommissionSettings').addEventListener('click',()=>{const per=Number($('settingsCommissionPerScan').value),pct=Number($('settingsCommissionSalesRate').value);if(!Number.isFinite(per)||per<0||!Number.isFinite(pct)||pct<0){$('commissionSettingsStatus').textContent='Enter valid non-negative commission rates.';return}localStorage.setItem(COMMISSION_RATE_KEY,JSON.stringify({perScan:per,salesPercent:pct}));renderCommissionSettings();$('commissionSettingsStatus').textContent='Commission rates saved and included in your next backup.';persist(true);status('Commission rates updated in App Settings.')});
