$('driveBackupNow').addEventListener('click',()=>performDriveBackup(true));
$('driveRestore').addEventListener('click',restoreDriveBackup);
$('driveDisconnect').addEventListener('click',async()=>{try{if(driveSession)await workerRequest('/disconnect',{method:'POST',body:'{}'})}catch(e){console.warn('Drive disconnect request failed',e)}driveSession='';localStorage.removeItem(DRIVE_SESSION_KEY);localStorage.removeItem(DRIVE_SYNC_HOLD_KEY);localStorage.removeItem(DRIVE_DEVICE_READY_KEY);$('driveBackupNow').disabled=true;$('driveRestore').disabled=true;driveStatus('Disconnected. Local diary saving continues as normal.','Not connected')});
async function cloudBackupAvailable(status){if(status?.lastBackupAt)return true;try{const found=await workerRequest('/restore',{method:'GET'});return !!found.backup}catch(err){if(/No XC ShiftApp cloud backup was found/.test(err.message))return false;throw err}}
async function handleDriveAuthReturn(){const params=new URLSearchParams(location.search),ticket=params.get('drive_ticket'),auth=params.get('drive_auth');if(!ticket&&!auth)return;if(auth==='error'){history.replaceState({},document.title,location.pathname+location.hash);const reason=params.get('drive_reason');driveStatus('Google authorisation was not completed. '+(reason||'Please check the Worker and Google OAuth setup, then try again.'),'Not connected');return}if(!ticket)return;try{const result=await workerRequest('/auth/exchange',{method:'POST',body:JSON.stringify({ticket})});history.replaceState({},document.title,location.pathname+location.hash);driveSession=result.sessionToken;localStorage.setItem(DRIVE_SESSION_KEY,driveSession);$('driveBackupNow').disabled=false;$('driveRestore').disabled=false;const cloud=await workerRequest('/status',{method:'GET'});if(await cloudBackupAvailable(cloud)){localStorage.setItem(DRIVE_SYNC_HOLD_KEY,'1');driveStatus('Google Drive connected. An existing cloud diary was found. Select Import from cloud before syncing this device; your local diary has not been uploaded.','Cloud backup found')}else{localStorage.removeItem(DRIVE_SYNC_HOLD_KEY);localStorage.setItem(DRIVE_DEVICE_READY_KEY,'1');driveStatus('Google Drive connected. No previous cloud backup was found, so this device will create the first backup.','Connected');await performDriveBackup()}}catch(err){driveStatus('Could not finish Google authorisation. '+err.message+' You can refresh this page to retry while the one-time ticket is still valid.','Error')}}
async function restoreDriveSession(){driveSession=localStorage.getItem(DRIVE_SESSION_KEY)||'';if(!driveSession)return;try{const result=await workerRequest('/status',{method:'GET'});$('driveBackupNow').disabled=false;$('driveRestore').disabled=false;if(await cloudBackupAvailable(result)&&!localStorage.getItem(DRIVE_DEVICE_READY_KEY)){localStorage.setItem(DRIVE_SYNC_HOLD_KEY,'1');driveStatus('An existing Google Drive backup is available. Import it to this device before syncing, or choose Back up now to deliberately upload this device’s diary.','Import required')}else{driveStatus(result.lastBackupAt?'Connected · Last backup '+new Date(result.lastBackupAt).toLocaleString('en-GB'):'Connected. No cloud backup has completed yet.','Connected');if(localStorage.getItem(DRIVE_PENDING_KEY)==='1'&&localStorage.getItem(DRIVE_SYNC_HOLD_KEY)!=='1')performDriveBackup()}}catch(err){if(err.status===401){driveSession='';localStorage.removeItem(DRIVE_SESSION_KEY);$('driveBackupNow').disabled=true;$('driveRestore').disabled=true;driveStatus('Google Drive needs reconnecting. Your diary remains saved locally. '+err.message,'Reconnect')}else{driveStatus('Could not check Google Drive just now. Your saved connection has been kept; it will retry when you are online. '+err.message,'Waiting')}}}
window.addEventListener('online',()=>{if(localStorage.getItem(DRIVE_PENDING_KEY)==='1'&&driveSession&&localStorage.getItem(DRIVE_SYNC_HOLD_KEY)!=='1')performDriveBackup()});
if(localStorage.getItem(DRIVE_PENDING_KEY)==='1')driveStatus('A cloud backup is waiting. It will sync when Google Drive is connected and online.','Waiting');
window.addEventListener('pagehide',()=>persist(true,true));
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')persist(true,true)});
function load(){try{const raw=localStorage.getItem(STORE);if(raw){const s=JSON.parse(raw);if(s&&s.appId===APP_ID){applyCurrentShift(s);state.archivedShifts=Array.isArray(s.archivedShifts)?s.archivedShifts:[]}}}catch(err){console.warn('Saved shift could not be read',err);status('Saved data could not be read.')}render();renderArchivedShifts()}
function linkedHeadcodes(record){const valid=v=>{const h=String(v||'').trim().toUpperCase().replace(/^\[|\]$/g,'');return /^[0-9][A-Z][0-9]{2}$/.test(h)?h:''};const values=[...(Array.isArray(record?.relatedTrainHeadcodes)?record.relatedTrainHeadcodes:[]),record?.relatedTrainHeadcode,record?.headcode,record?.trainHeadcode];if(Array.isArray(record?.relatedTrainIds))for(const id of record.relatedTrainIds){const t=state.trains.find(x=>x.id&&x.id===id);values.push(t?.headcode)}if(record?.relatedTrainId){const t=state.trains.find(x=>x.id&&x.id===record.relatedTrainId);values.push(t?.headcode)}const label=String(record?.relatedTrainLabel||'');values.push(...(label.match(/\b\d[A-Z]\d{2}\b/gi)||[]));if(!values.some(valid)){const text=String(record?.text||'');values.push(...(text.match(/\[([0-9][A-Z][0-9]{2})\]/gi)||[]).map(x=>x.slice(1,-1)))}return [...new Set(values.map(valid).filter(Boolean))]};function linkedHeadcode(record){return linkedHeadcodes(record)[0]||''}
function entryDetails(e){const headcodes=linkedHeadcodes(e);const stripRepeatedHeadcode=value=>{let text=String(value||'No details recorded').replace(/\\n/g,'\n');for(const hc of headcodes)text=text.replace(new RegExp('\\['+hc+'\\]','gi'),'');if(e.type==='Passenger Counts')text=text.replace(/\s*[·|,;—-]\s*(?:Train portion|Applies to)\s*:\s*[^\n]*/gi,'').replace(/^\s*(?:Train portion|Applies to)\s*:\s*[^\n]*\n?/gim,'');return text.split('\n').map(line=>line.replace(/^\s*[-–—:|]\s*/, '').replace(/\s*[-–—:|]\s*$/, '').replace(/[ \t]{2,}/g,' ').trim()).filter(Boolean).join('\n')};const updates=Array.isArray(e.updates)?e.updates.map(u=>`\n\nUPDATE — ${fmt(u.timestamp)}\n${stripRepeatedHeadcode(u.text)}`):[];const passengerMeta=e.type==='Passenger Counts'?[...(e.fullStanding===true?['Full and standing']:[]),...(Array.isArray(e.trainSets)&&e.trainSets.length?[`Train portion: ${e.trainSets.join(', ')}`]:[])]:[];return [...(e.type==='Photo'&&e.photoTitle?[e.photoTitle]:[]),...headcodes.map(h=>`[${h}]`),...(e.logNumber?[`Log / reference number: ${e.logNumber}`]:[]),...(e.type==='Incident'&&e.incidentLocation?[`Incident location: ${e.incidentLocation}`]:[]),(e.type==='Voice note'?`Description: ${e.voiceDescription||e.text||''}`:stripRepeatedHeadcode(e.text)),...passengerMeta,...updates].filter(Boolean).join('\n')}
function entryDetailsHtml(e,includeLeadingHeadcode=true){const lines=entryDetails(e).split('\n');const headcode=linkedHeadcode(e);if(!includeLeadingHeadcode&&headcode&&lines[0]===`[${headcode}]`)lines.shift();return lines.map(line=>line.split(/(\[[0-9][A-Z][0-9]{2}\])/gi).map(part=>/^\[[0-9][A-Z][0-9]{2}\]$/i.test(part)?`<strong class="headcode-highlight" style="color:#c00035 !important;font-weight:900 !important">${esc(part.toUpperCase())}</strong>`:esc(part)).join('')).join('<br>')}
function incidentUpdatesHtml(entry,entryIndex,archived=false){if(entry?.type!=='Incident'||!Array.isArray(entry.updates)||!entry.updates.length)return '';return `<section class="incident-updates"><strong>Incident updates (${entry.updates.length})</strong>${entry.updates.map((u,n)=>`<div class="incident-update-item"><div class="incident-update-heading"><span>Update · ${esc(fmt(u.timestamp))}${u.editedAt?' · Edited':''}</span><button type="button" class="entry-action incident-update-edit" ${archived?`data-archive-edit-update="${entryIndex}"`:`data-edit-incident-update="${entryIndex}"`} data-update-index="${n}" aria-label="Edit incident update" title="Edit update">✏️</button></div><p>${esc(u.text||'').replace(/\n/g,'<br>')}</p></div>`).join('')}</section>`}
function defectMeta(e){if(e?.type!=='Defect')return null;const text=String(e.text||'');const unit=(text.match(/\bUnit\s+(\d{6})\b/i)||[])[1]||'';const pvn=(text.match(/\bPVN\s+(\d+)\b/i)||[])[1]||'';return unit?{unit,pvn,headcode:linkedHeadcode(e)}:null}
function passengerGroupHeadcode(entry){const valid=value=>{const hc=String(value||'').trim().toUpperCase().replace(/^\[|\]$/g,'');return /^[0-9][A-Z][0-9]{2}$/.test(hc)?hc:''};const direct=[entry?.relatedTrainHeadcode,entry?.headcode,entry?.trainHeadcode];for(const value of direct){const hc=valid(value);if(hc)return hc}if(entry?.relatedTrainId){const train=state.trains.find(t=>t.id&&t.id===entry.relatedTrainId);const hc=valid(train?.headcode);if(hc)return hc}if(Array.isArray(entry?.relatedTrainIds)){for(const id of entry.relatedTrainIds){const train=state.trains.find(t=>t.id&&t.id===id);const hc=valid(train?.headcode);if(hc)return hc}}const linked=linkedHeadcodes(entry);if(linked.length)return linked[0];const text=String(entry?.text||'');const match=text.match(/(?:Headcode|Train)\s*[:#-]\s*([0-9][A-Z][0-9]{2})/i)||text.match(/\[([0-9][A-Z][0-9]{2})\]/i);return valid(match?.[1])||'NO-HEADC0DE'}
function groupedEntries(entries){const defectGroups=new Map(),passengerGroups=new Map();entries.forEach((e,index)=>{const meta=defectMeta(e);if(meta){if(!defectGroups.has(meta.unit))defectGroups.set(meta.unit,{meta:{unit:meta.unit},items:[]});defectGroups.get(meta.unit).items.push({entry:e,index,meta})}if(e.type==='Passenger Counts'){const hc=passengerGroupHeadcode(e);if(!passengerGroups.has(hc))passengerGroups.set(hc,{headcode:hc,items:[]});passengerGroups.get(hc).items.push({entry:e,index})}});const firstIndex=new Map(),consumed=new Set();for(const g of defectGroups.values())if(g.items.length>1){firstIndex.set(g.items[0].index,{kind:'defectGroup',meta:g.meta,items:g.items});g.items.slice(1).forEach(x=>consumed.add(x.index))}for(const g of passengerGroups.values()){firstIndex.set(g.items[0].index,{kind:'passengerGroup',headcode:g.headcode,items:g.items});g.items.slice(1).forEach(x=>consumed.add(x.index))}const out=[];entries.forEach((entry,index)=>{if(consumed.has(index))return;out.push(firstIndex.get(index)||{kind:'single',entry,index})});return out}
function passengerStationName(value){let name=String(value||'').trim();if(!name)return 'Location not recorded';name=name.replace(/\s*(?:[·|,;—-]\s*)?(?:Train portion|Applies to)\s*:\s*.*$/i,'').trim();name=name.replace(/\s*\([A-Z]{3}\)\s*$/,'').trim();return name||'Location not recorded'}
function passengerGroupRows(group){return group.items.map(x=>{const text=String(x.entry.text||''),counts=x.entry.passengerCounts||{};return {station:passengerStationName(counts.station||(text.match(/Location:\s*([^\n]+)/i)||[])[1]),first:Number.isFinite(Number(counts.first))?Number(counts.first):(Number((text.match(/First Class:\s*(\d+)/i)||[])[1])||0),standard:Number.isFinite(Number(counts.standard))?Number(counts.standard):(Number((text.match(/Standard Class:\s*(\d+)/i)||[])[1])||0),formation:counts.trainPortion||x.entry.trainSets?.[0]||((text.match(/(?:Applies to|Train portion):\s*([^\n]+)/i)||[])[1]?.trim())||'Whole Train',fullStanding:x.entry.fullStanding===true,stationChecked:x.entry.stationChecked===true,entry:x.entry,index:x.index}})}
async function copyPassengerGroupTable(group){const rows=passengerGroupRows(group);const heading=`Passenger Counts${group.headcode!=='NO-HEADC0DE'?' — '+group.headcode:''}`;const text=[heading,'Station | First Class | Standard Class',...rows.map(r=>`${r.station}${r.stationChecked?' ✓':''} | ${r.first} | ${r.standard}${r.fullStanding?' | FULL AND STANDING':''}`)].join('\n');try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else fallbackCopy(text);status('Passenger count table copied to clipboard.')}catch(err){try{fallbackCopy(text);status('Passenger count table copied to clipboard.')}catch(e){status('Could not copy passenger count table. Check clipboard permissions.')}}}
async function savePassengerGroupAsJpeg(group){const rows=passengerGroupRows(group),notes=group.items.map(x=>{const m=String(x.entry.text||'').match(/^Notes(?:\s*\([^\n]*?\))?:\s*([\s\S]*?)(?=\n[A-Z][^\n]*:|$)/im);return m&&m[1].trim()?{time:fmt(x.entry.timestamp),text:m[1].trim()}:null}).filter(Boolean);const width=1200,pad=64,rowH=66,tableTop=270,notesHeight=notes.length?notes.reduce((n,x)=>n+Math.max(54,Math.ceil(x.text.length/75)*36),0)+70:0,standing=rows.some(r=>r.fullStanding)?58:0,height=tableTop+78+rows.length*rowH+notesHeight+standing+100;const c=document.createElement('canvas');c.width=width;c.height=height;const x=c.getContext('2d');x.fillStyle='#f5f2f3';x.fillRect(0,0,width,height);x.fillStyle='#A50034';x.fillRect(0,0,width,190);x.fillStyle='#fff';x.font='bold 30px Arial';x.fillText('CROSSCOUNTRY',pad,62);x.font='bold 43px Arial';x.fillText('PASSENGER COUNTS',pad,126);x.font='26px Arial';x.fillText(`${group.headcode!=='NO-HEADC0DE'?group.headcode+' · ':''}${fmt(group.items[0]?.entry.timestamp)}`,pad,166);const left=pad,cols=[left,left+530,left+800,width-pad];x.fillStyle='#fff';x.fillRect(left,220,width-pad*2,height-270);let y=tableTop;x.fillStyle='#eee5e9';x.fillRect(left,y,width-pad*2,58);x.fillStyle='#251c22';x.font='bold 25px Arial';x.fillText('Station',left+18,y+38);x.fillText('First Class',cols[1]+18,y+38);x.fillText('Standard',cols[2]+18,y+38);y+=58;rows.forEach((r,i)=>{x.fillStyle=r.fullStanding?'#ffe5e7':(i%2?'#faf8f9':'#fff');x.fillRect(left,y,width-pad*2,rowH);x.strokeStyle='#d3c8ce';x.lineWidth=2;x.strokeRect(left,y,width-pad*2,rowH);x.beginPath();x.moveTo(cols[1],y);x.lineTo(cols[1],y+rowH);x.moveTo(cols[2],y);x.lineTo(cols[2],y+rowH);x.stroke();x.fillStyle=r.fullStanding?'#8f001f':'#252025';x.font=r.fullStanding?'bold 25px Arial':'25px Arial';x.fillText(r.station+(r.stationChecked?' ✓':''),left+18,y+42);x.textAlign='center';x.fillText(String(r.first), (cols[1]+cols[2])/2,y+42);x.fillText(String(r.standard),(cols[2]+cols[3])/2,y+42);x.textAlign='left';if(r.fullStanding){x.font='bold 18px Arial';x.fillText('FULL AND STANDING',cols[3]-215,y+42)}y+=rowH});if(notes.length){y+=30;x.fillStyle='#252025';x.font='bold 25px Arial';x.fillText('NOTES',left+8,y);y+=42;for(const n of notes){x.font='20px Arial';x.fillStyle='#655b61';x.fillText(n.time,left+8,y);y+=30;const words=n.text.split(/\s+/);let line='';for(const word of words){const test=line?line+' '+word:word;if(x.measureText(test).width>width-pad*2-30&&line){x.fillStyle='#252025';x.fillText(line,left+8,y);y+=30;line=word}else line=test}if(line){x.fillStyle='#252025';x.fillText(line,left+8,y);y+=34}}}x.fillStyle='#6d6268';x.font='20px Arial';x.fillText('Staff Shift App · Passenger count record',pad,height-34);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/jpeg',.92));if(!blob)throw new Error('JPEG export failed');const safe=(group.headcode||'unassigned').toLowerCase().replace(/[^a-z0-9]+/g,'-');const file=new File([blob],`passenger-counts-${safe}-${new Date().toISOString().slice(0,10)}.jpg`,{type:'image/jpeg'});if(navigator.canShare&&navigator.canShare({files:[file]})&&navigator.share){await navigator.share({files:[file],title:file.name});status('Passenger counts JPEG ready to save or share.')}else{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);status('Passenger counts exported as JPEG.')}}
function passengerGroupHtml(group){const rows=passengerGroupRows(group);const notes=group.items.map(x=>{const m=String(x.entry.text||'').match(/^Notes(?:\s*\([^\n]*?\))?:\s*([\s\S]*?)(?=\n[A-Z][^\n]*:|$)/im);return m&&m[1].trim()?{entry:x.entry,text:m[1].trim()}:null}).filter(Boolean);return `<article class="entry passenger-count-group"><div class="entrytop"><span> 🔢 PASSENGER COUNTS${group.headcode!=='NO-HEADC0DE'?` <strong class="headcode-highlight">[${esc(group.headcode)}]</strong>`:''} <span class="incident-ref-marker">${group.items.length} entries</span><button type="button" class="entry-action passenger-copy-table" data-copy-passenger-table="${esc(group.headcode)}" aria-label="Copy passenger count table" title="Copy passenger count table">📋</button><button type="button" class="entry-action passenger-save-image" data-save-passenger-table="${esc(group.headcode)}" aria-label="Save passenger counts as JPEG" title="Save passenger counts as JPEG">🖼️</button><button type="button" class="entry-action passenger-delete-train" data-delete-passenger-train="${esc(group.headcode)}" aria-label="Delete all passenger counts for this train" title="Delete all counts for this train">🗑️</button></span><time>${esc(fmt(group.items[0].entry.timestamp))}</time></div><div class="passenger-table-wrap"><table class="passenger-count-table"><thead><tr><th>Station</th><th>First Class</th><th>Standard Class</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.fullStanding?'full-standing-row':''}"><td><button type="button" class="passenger-station-toggle${r.stationChecked?' is-checked':''}" data-passenger-station-toggle="${r.index}" aria-pressed="${r.stationChecked?'true':'false'}" title="Tap to mark this station as checked"><span>${esc(r.station)}</span><span class="station-tick" aria-hidden="true">${r.stationChecked?'✓':''}</span></button></td><td>${r.first}</td><td>${r.standard}</td></tr>`).join('')}</tbody></table></div>${notes.length?`<section class="passenger-notes"><h4>📝 Notes for ${group.headcode!=='NO-HEADC0DE'?esc(group.headcode):'this train'}</h4>${notes.map(n=>`<p><strong>${esc(fmt(n.entry.timestamp))}${group.headcode!=='NO-HEADC0DE'?' · '+esc(group.headcode):''}</strong><br>${esc(n.text).replace(/\n/g,'<br>')}</p>`).join('')}</section>`:''}${group.items.filter(x=>x.entry.fullStanding).map(x=>`<p class="full-standing-note">🔴 FULL AND STANDING · ${esc(fmt(x.entry.timestamp))} · ${esc(group.headcode)}</p>`).join('')}${group.items.map(x=>`<details><summary>${esc(fmt(x.entry.timestamp))} · ${esc((String(x.entry.text||'').match(/Location:\s*([^\n]+)/i)||[])[1]||'Location not recorded')} <button type="button" class="entry-action passenger-edit-trigger" data-edit-passenger="${x.index}" aria-label="Edit passenger count" title="Edit passenger count">✏️</button> <button type="button" class="entry-action passenger-delete-trigger" data-delete-passenger="${x.index}" aria-label="Delete this passenger count" title="Delete this passenger count">🗑️</button></summary><p>${entryDetailsHtml(x.entry,false)}</p></details>`).join('')}</article>`} 

function defectDetailText(e,meta){let text=entryDetails(e);const headcode=linkedHeadcode(e);if(headcode&&text.startsWith(`[${headcode}]\n`))text=text.slice(headcode.length+3);return text.split('\n').map(line=>line.replace(new RegExp('\s*[·|]\s*Unit\s+'+(meta.unit||'')+'\\b','i'),'').replace(/\s*[·|]\s*PVN\s+\d+\b/i,'').replace(/[ \t]{2,}/g,' ').trim()).join('\n')}
function passengerGroupPdfHtml(group){const rows=passengerGroupRows(group);const notes=group.items.map(x=>{const m=String(x.entry.text||'').match(/^Notes(?:\s*\([^\n]*?\))?:\s*([\s\S]*?)(?=\n[A-Z][^\n]*:|$)/im);return m&&m[1].trim()?{entry:x.entry,text:m[1].trim()}:null}).filter(Boolean);return `<div class="passenger-pdf-report"><table class="passenger-count-table" style="width:100%;border-collapse:collapse;margin:8px 0 12px;font-size:13px"><thead><tr><th style="background:#f1e8ec;color:#241821;border:1px solid #cfc5ca;padding:7px;text-align:left">Station</th><th style="background:#f1e8ec;color:#241821;border:1px solid #cfc5ca;padding:7px;text-align:center">First Class</th><th style="background:#f1e8ec;color:#241821;border:1px solid #cfc5ca;padding:7px;text-align:center">Standard Class</th></tr></thead><tbody>${rows.map(r=>`<tr${r.fullStanding?' style="background:#ffe5e7;color:#8f001f;font-weight:700"':''}><td style="border:1px solid #cfc5ca;padding:7px">${esc(r.station)}${r.stationChecked?' ✓':''}</td><td style="border:1px solid #cfc5ca;padding:7px;text-align:center">${r.first}</td><td style="border:1px solid #cfc5ca;padding:7px;text-align:center">${r.standard}</td></tr>`).join('')}</tbody></table>${notes.length?`<div class="passenger-pdf-notes"><strong>Notes${group.headcode!=='NO-HEADC0DE'?' — '+esc(group.headcode):''}</strong>${notes.map(n=>`<p style="margin:4px 0"><b>${esc(fmt(n.entry.timestamp))}</b><br>${esc(n.text).replace(/\n/g,'<br>')}</p>`).join('')}</div>`:''}${group.items.filter(x=>x.entry.fullStanding).map(x=>`<p style="margin:4px 0;color:#8f001f;font-weight:700">FULL AND STANDING — ${esc(fmt(x.entry.timestamp))}${group.headcode!=='NO-HEADC0DE'?' — '+esc(group.headcode):''}</p>`).join('')}</div>`}
function passengerGroupPlain(group){const rows=passengerGroupRows(group);const notes=group.items.map(x=>{const m=String(x.entry.text||'').match(/^Notes(?:\s*\([^\n]*?\))?:\s*([\s\S]*?)(?=\n[A-Z][^\n]*:|$)/im);return m&&m[1].trim()?`     ${fmt(x.entry.timestamp)}${group.headcode!=='NO-HEADC0DE'?' · '+group.headcode:''}: ${m[1].trim()}`:null}).filter(Boolean);const standing=rows.filter(r=>r.fullStanding).map(r=>`     🔴 FULL AND STANDING · ${fmt(r.entry.timestamp)}${group.headcode!=='NO-HEADC0DE'?' · '+group.headcode:''}`);return `🔢 PASSENGER COUNTS${group.headcode!=='NO-HEADC0DE'?' — '+group.headcode:''}\nStation | First Class | Standard Class\n${rows.map(r=>`${r.station}${r.stationChecked?' ✓':''} | ${r.first} | ${r.standard}${r.fullStanding?' | FULL AND STANDING':''}`).join('\n')}${notes.length?'\n\n📝 NOTES\n'+notes.join('\n'):''}${standing.length?'\n\n'+standing.join('\n'):''}` }
function defectGroupPlain(group){const {meta,items}=group;const byPvn=new Map();items.forEach(x=>{const pvn=x.meta.pvn||'PVN not recorded';if(!byPvn.has(pvn))byPvn.set(pvn,[]);byPvn.get(pvn).push(x)});return `🔧 DEFECTS — UNIT ${meta.unit} (${items.length})\n${[...byPvn].map(([pvn,list])=>`     ${pvn==='PVN not recorded'?pvn:`PVN ${pvn}`}\n${list.map((x,i)=>`       Defect ${i+1}${x.meta.headcode?` [${x.meta.headcode}]`:''} · ${fmt(x.entry.timestamp)}\n${defectDetailText(x.entry,meta).split('\n').map(line=>'          '+line).join('\n')}`).join('\n')}`).join('\n')}`}
function defectGroupHtml(group){const {meta,items}=group;const byPvn=new Map();items.forEach(x=>{const pvn=x.meta.pvn||'PVN not recorded';if(!byPvn.has(pvn))byPvn.set(pvn,[]);byPvn.get(pvn).push(x)});let n=0;return `<article class="entry defect-group"><div class="entrytop"><span>🔧 DEFECTS (${items.length})</span><time>${esc(fmt(items[0].entry.timestamp))}</time></div><div class="defect-group-meta">UNIT ${esc(meta.unit)}</div>${[...byPvn].map(([pvn,list])=>`<section class="defect-pvn-group"><div class="defect-pvn-heading">${pvn==='PVN not recorded'?pvn:`PVN ${esc(pvn)}`}</div>${list.map(x=>{n++;return `<div class="defect-group-item"><div class="defect-group-item-head"><strong>Defect ${n}${x.meta.headcode?` · <span class="headcode-highlight">${esc(x.meta.headcode)}</span>`:''}</strong><time>${esc(fmt(x.entry.timestamp))}${x.entry.editedAt?' · Edited':''}</time><button type="button" class="entry-action entry-menu-trigger" data-entry-menu="${x.index}" aria-label="More options for defect ${n}">⋯</button></div><p>${esc(defectDetailText(x.entry,meta)).replace(/\n/g,'<br>')}</p></div>`}).join('')}</section>`).join('')}</article>`}

function renderArchiveCalendar(){
 const host=$('archiveCalendarDays');if(!host)return;const y=archiveCalendarMonth.getFullYear(),m=archiveCalendarMonth.getMonth();$('archiveCalTitle').textContent=archiveCalendarMonth.toLocaleDateString('en-GB',{month:'long',year:'numeric'});
 const first=new Date(y,m,1),offset=first.getDay(),days=new Date(y,m+1,0).getDate();const byDate=new Map();state.archivedShifts.forEach(r=>{const d=String(r.shift?.date||'').slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(d))return;if(!byDate.has(d))byDate.set(d,[]);byDate.get(d).push(r)});
 let html='';for(let i=0;i<offset;i++)html+='<span class="archive-cal-empty"></span>';
 for(let day=1;day<=days;day++){const key=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,items=byDate.get(key)||[],dayRaw=calendarCodes[key]||[],dayCodes=Array.isArray(dayRaw)?dayRaw:(dayRaw?[dayRaw]:[]),dayCode=dayCodes[0]||'',jobNumbers=items.map(r=>String(r.shift?.jobNumber||'').trim().toUpperCase()),activityType=jobNumbers.some(j=>['REFRESH','ROUTES'].includes(j)),otherActivity=jobNumbers.includes('OTHER'),hasContent=items.some(r=>(r.entries||[]).length||(r.trains||[]).length||String(r.shift?.notes||'').trim()||String(r.shift?.jobNumber||'').trim());
 const hasRDW=dayCodes.includes('RDW')||items.some(r=>!!r.shift?.rdw);const hasARShift=items.some(r=>/^(?:A\/R|AR|SPARE)(?:\s|$)/i.test(String(r.shift?.jobNumber||'').trim()));const codeClass=dayCodes.includes('SB')?'calendar-sb':dayCodes.includes('RD')?'calendar-rd':dayCodes.some(c=>['AL','ALR'].includes(c))?'calendar-al':dayCodes.includes('ZF')?'calendar-zf':'';
 const payday=isCommissionPayday(key);
 const jobs=items.map(r=>{const raw=String(r.shift?.jobNumber||'').trim().toUpperCase();let label;if(/^A\/R(?:\s|$)/.test(raw)){const supplied=raw.replace(/^A\/R\s*/,'').trim();const rawStart=String(r.shift?.bookOn||'').trim();const start=/^\d{4}$/.test(rawStart)?`${rawStart.slice(0,2)}:${rawStart.slice(2)}`:rawStart;const detail=supplied||start;label=`AR${detail?`<br>${esc(detail)}`:''}`}else if(raw==='RR')label=esc(raw);else{const match=raw.match(/^([A-Z]+)\s*0*(\d+)$/);label=match?`${esc(match[1])}<br>${esc(String(Number(match[2])))}`:esc(raw||'—')}const on=String(r.shift?.bookOn||'').trim(),off=String(r.shift?.bookOff||'').trim(),times=on||off?`<span class="calendar-shift-times">${esc(on||'—')}–${esc(off||'—')}</span>`:'',rdwMark=r.shift?.rdw?'<span class="calendar-rdw-icon" title="Rest Day Work" aria-label="Rest Day Work">💰</span>':'';return `<span class="calendar-shift-item">${label}${rdwMark}${times}</span>`}).join('');
 html+=`<button type="button" class="archive-cal-day ${codeClass} ${(hasContent||hasRDW)?'has-content':''} ${otherActivity&&!activityType?'activity-blue':''} ${activityType?'activity-yellow':''} ${items.length?'has-archive':''} ${hasARShift?'ar-shift':''} ${payday?'calendar-payday':''} ${selectedArchiveDate===key?'selected':''}" data-cal-date="${key}" aria-label="${day}${payday?' payday':''} ${dayCode?dayCode+' ':''}${items.length} archived shift(s)">${day}${payday?'<span class="calendar-payday-icon" aria-hidden="true">💷</span>':''}${hasRDW&&!items.some(r=>r.shift?.rdw)?'<span class="calendar-payday-icon" aria-hidden="true">💰</span>':''}${(items.length||dayCode)?`<small>${dayCodes.length?`<span class="calendar-code">${dayCodes.map(c=>esc(c)).join(' · ')}</span>${leaveScheduledTimes[key]?`<span class="calendar-shift-times">${esc(leaveScheduledTimes[key].bookOn||'—')}–${esc(leaveScheduledTimes[key].bookOff||'—')}</span>`:''}`:''}${jobs}</small>`:''}</button>`;
 }
 host.innerHTML=html;
}
