$('calendarCodeRemove')?.addEventListener('click',()=>{const codes=[...document.querySelectorAll('input[name="calendarCodeType"]:checked')].map(x=>x.value);if(!codes.length){status('Tick the leave or unavailability types you want to remove.');return}let dates=[];if($('calendarDateMode').value==='range'){const start=$('calendarCodeStart').value,end=$('calendarCodeEnd').value;if(!start||!end){status('Select both a start and end date.');return}if(end<start){status('The end date must be on or after the start date.');return}const cur=new Date(start+'T12:00:00'),last=new Date(end+'T12:00:00');while(cur<=last){dates.push([cur.getFullYear(),String(cur.getMonth()+1).padStart(2,'0'),String(cur.getDate()).padStart(2,'0')].join('-'));cur.setDate(cur.getDate()+1)}}else{dates=[...new Set([...document.querySelectorAll('.calendar-individual-date')].map(x=>x.value).filter(Boolean))];if(!dates.length){status('Add at least one valid date.');return}}let removed=0;dates.forEach(key=>{const old=calendarCodes[key]||[],list=Array.isArray(old)?old:(old?[old]:[]),next=list.filter(c=>!codes.includes(c));if(next.length!==list.length)removed++;if(next.length)calendarCodes[key]=next;else delete calendarCodes[key];if((list.includes('AL')||list.includes('ALR'))&&(!next.includes('AL')&&!next.includes('ALR')))delete leaveScheduledTimes[key]});localStorage.setItem(CALENDAR_CODES_KEY,JSON.stringify(calendarCodes));localStorage.setItem(LEAVE_TIMES_KEY,JSON.stringify(leaveScheduledTimes));$('calendarCodeDialog').close();renderArchiveCalendar();status(`${codes.join(', ')} removed from ${removed} ${removed===1?'date':'dates'}.`)});
let pendingSafetyBriefEntry=null;
function applyCalendarCodeEntries(dates,codes){dates.forEach(key=>{const old=calendarCodes[key]||[],list=Array.isArray(old)?old:(old?[old]:[]);calendarCodes[key]=[...new Set([...list,...codes])]});localStorage.setItem(CALENDAR_CODES_KEY,JSON.stringify(calendarCodes));$('calendarCodeDialog').close();renderArchiveCalendar();status(`${codes.join(', ')} added to ${dates.length} ${dates.length===1?'date':'dates'}.`)}
function safetyBriefDefaultFinish(start){const [sh,sm]=String(start||'08:00').split(':').map(Number),[dh,dm]=getSpareTermLength().split(':').map(Number),mins=(sh*60+sm)+(dh*60+dm);return String(Math.floor((mins%1440)/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0')}
function startSafetyBriefTimeEntry(dates,codes){pendingSafetyBriefEntry={dates:[...dates],codes:[...codes],index:0,hours:{}};showSafetyBriefTimeEntry()}
