function updateVoiceTimer(){const seconds=voiceRecorder?.state==='recording'?voiceElapsedSeconds():Number($('voiceNoteTimer').dataset.seconds||0);const timer=$('voiceNoteTimer');timer.textContent=formatVoiceTime(seconds);timer.classList.remove('timer-green','timer-orange','timer-red','timer-idle');timer.classList.add(seconds<=60?'timer-green':seconds<=90?'timer-orange':'timer-red');timer.dataset.seconds=String(seconds)}
function stopVoiceTimer(){if(voiceTimerInterval){clearInterval(voiceTimerInterval);voiceTimerInterval=null}if(voiceStopTimeout){clearTimeout(voiceStopTimeout);voiceStopTimeout=null}}
function stopVoiceCapture(){stopVoiceTimer();if(voiceRecorder&&voiceRecorder.state==='recording'){try{voiceRecorder.stop()}catch{}}if(voiceStream){voiceStream.getTracks().forEach(t=>t.stop());voiceStream=null}$('voiceNoteStart').disabled=false;$('voiceNoteStop').disabled=true}
function clearVoiceRecording(){
  // Invalidate both a live recording and any pending microphone permission request.
  voiceRecordingToken++;voiceSaveToken++;stopVoiceTimer();
  const recorder=voiceRecorder;voiceRecorder=null;
  if(recorder){try{recorder.ondataavailable=null;recorder.onstop=null;recorder.onerror=null;if(recorder.state!=='inactive')recorder.stop()}catch{}}
  if(voiceStream){voiceStream.getTracks().forEach(track=>{try{track.stop()}catch{}});voiceStream=null}
  voiceChunks.length=0;voiceBlob=null;voiceRecordStartedAt=0;
  if(voicePreviewUrl){try{URL.revokeObjectURL(voicePreviewUrl)}catch{}voicePreviewUrl=''}
  const preview=$('voiceNotePreview');try{preview.pause()}catch{};try{preview.srcObject=null}catch{};preview.removeAttribute('src');preview.removeAttribute('srcset');try{preview.currentTime=0}catch{};preview.hidden=true;try{preview.load()}catch{};
  const timer=$('voiceNoteTimer');timer.dataset.seconds='0';timer.textContent='00:00';timer.classList.remove('timer-orange','timer-red','timer-idle');timer.classList.add('timer-green');
  $('voiceNoteStart').disabled=false;$('voiceNoteStop').disabled=true;$('voiceNoteSave').disabled=true;$('voiceNoteClear').disabled=true;$('voiceNoteRecordStatus').textContent='Recording cleared — start a new recording when ready';
}
function resetVoiceNoteRecorder(){clearVoiceRecording();$('voiceNoteRecordStatus').textContent='Not recording'}
function openVoiceNoteDialog(){$('voiceNoteForm').reset();resetVoiceNoteRecorder();$('voiceNoteDialog').showModal();$('voiceNoteTitle').focus()}
$('voiceNoteStart').addEventListener('click',async()=>{if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){status('Voice recording is not supported by this browser. Use the app over HTTPS on a supported device.');return}const requestToken=++voiceRecordingToken;$('voiceNoteStart').disabled=true;$('voiceNoteClear').disabled=false;$('voiceNoteRecordStatus').textContent='Waiting for microphone permission…';try{const requestedStream=await navigator.mediaDevices.getUserMedia({audio:true});if(requestToken!==voiceRecordingToken){requestedStream.getTracks().forEach(track=>track.stop());return}voiceStream=requestedStream;const mime=['audio/mp4','audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported?.(t));const recorder=new MediaRecorder(voiceStream,{...(mime?{mimeType:mime}:{}),audioBitsPerSecond:16000});const token=requestToken;voiceRecorder=recorder;voiceChunks=[];voiceBlob=null;voiceRecordStartedAt=Date.now();$('voiceNoteTimer').dataset.seconds='0';updateVoiceTimer();recorder.ondataavailable=e=>{if(token===voiceRecordingToken&&e.data?.size)voiceChunks.push(e.data)};recorder.onerror=()=>{if(token===voiceRecordingToken){$('voiceNoteRecordStatus').textContent='Recording error — please try again';clearVoiceRecording()}};recorder.onstop=()=>{if(token!==voiceRecordingToken)return;stopVoiceTimer();if(!voiceChunks.length){$('voiceNoteRecordStatus').textContent='No audio was captured. Please try again.';voiceRecorder=null;return}const recordedBlob=new Blob(voiceChunks,{type:recorder.mimeType||voiceChunks[0]?.type||'audio/webm'});if(recordedBlob.size>2*1024*1024){voiceBlob=null;$('voiceNoteRecordStatus').textContent='Recording too large. Please record a shorter note.';$('voiceNoteSave').disabled=true;voiceRecorder=null;return}voiceBlob=recordedBlob;if(voicePreviewUrl)URL.revokeObjectURL(voicePreviewUrl);voicePreviewUrl=URL.createObjectURL(voiceBlob);$('voiceNotePreview').src=voicePreviewUrl;$('voiceNotePreview').hidden=false;$('voiceNoteSave').disabled=false;$('voiceNoteClear').disabled=false;$('voiceNoteStart').disabled=false;$('voiceNoteStop').disabled=true;$('voiceNoteRecordStatus').textContent=`Recording ready · ${formatVoiceTime(Number($('voiceNoteTimer').dataset.seconds||0))} · ${(voiceBlob.size/1024).toFixed(0)} KB`;$('voiceNotePreview').load();voiceRecorder=null};recorder.start(250);$('voiceNoteStart').disabled=true;$('voiceNoteStop').disabled=false;$('voiceNoteClear').disabled=false;$('voiceNoteSave').disabled=true;$('voiceNoteRecordStatus').textContent='🔴 Recording…';voiceTimerInterval=setInterval(updateVoiceTimer,200);voiceStopTimeout=setTimeout(()=>{if(token===voiceRecordingToken&&recorder.state==='recording'){$('voiceNoteTimer').dataset.seconds='120';updateVoiceTimer();$('voiceNoteRecordStatus').textContent='⏱️ 2-minute limit reached · recording stopped automatically';stopVoiceCapture()}},120000)}catch(err){if(requestToken!==voiceRecordingToken)return;console.warn('Microphone access failed',err);if(voiceStream){voiceStream.getTracks().forEach(t=>t.stop());voiceStream=null}stopVoiceTimer();$('voiceNoteStart').disabled=false;$('voiceNoteClear').disabled=true;$('voiceNoteRecordStatus').textContent='Microphone unavailable';status('Microphone access was blocked or unavailable. Check your browser microphone permissions.')}});
$('voiceNoteStop').addEventListener('click',()=>{if(voiceRecorder?.state==='recording'){updateVoiceTimer();stopVoiceCapture()}});
$('voiceNoteClear').addEventListener('click',e=>{e.preventDefault();e.stopPropagation();clearVoiceRecording();});
$('voiceNoteForm').addEventListener('submit',async e=>{e.preventDefault();if(voiceSaving)return;const title=$('voiceNoteTitle').value.trim(),description=$('voiceNoteDescription').value.trim();if(!title||!description){status('Enter a title and brief description for the voice note.');return}if(voiceRecorder?.state==='recording'){status('Stop the recording before attaching it to the log.');return}if(!voiceBlob){status('Record and stop a voice note before saving.');return}voiceSaving=true;const saveToken=++voiceSaveToken,recordingToken=voiceRecordingToken;$('voiceNoteSave').disabled=true;$('voiceNoteClear').disabled=true;$('voiceNoteSave').textContent='Saving…';try{const blobToSave=voiceBlob;const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error||new Error('Audio could not be read'));r.readAsDataURL(blobToSave)});if(saveToken!==voiceSaveToken||recordingToken!==voiceRecordingToken||!voiceBlob)throw new Error('The recording was cleared before it could be attached.');const mime=blobToSave.type||'audio/webm',ext=mime.includes('mp4')?'m4a':mime.includes('ogg')?'ogg':'webm',time=archiveEditingRecord?archiveTimestamp(archiveEditingRecord.shift?.date):stamp(),fileName=`voice-note-${new Date().toISOString().replace(/[:.]/g,'-')}.${ext}`;const entry={id:crypto.randomUUID?crypto.randomUUID():String(Date.now())+'-'+Math.random().toString(16).slice(2),type:'Voice note',voiceTitle:title,voiceDescription:description,voiceFileName:fileName,audioData:data,text:`${title}\n${description}`,timestamp:time};state.entries.push(entry);if(archiveEditingRecord){finishArchiveEdit('Voice note attached to the archived shift log.');$('voiceNoteDialog').close();resetVoiceNoteRecorder();return}render();if(!persist()){state.entries.pop();render();throw new Error('The voice note could not be saved to device storage. Check available storage and try a shorter recording.')} $('voiceNoteDialog').close();resetVoiceNoteRecorder();type.value='General Note';fields();status('Voice note successfully attached to the shift log and saved on this device. Use “Save audio to device” to download a copy.')}catch(err){console.warn('Voice note save failed',err);$('voiceNoteSave').disabled=!voiceBlob;status(err.message||'The voice note could not be attached. Please try again.')}finally{voiceSaving=false;$('voiceNoteSave').textContent='Save voice note';$('voiceNoteClear').disabled=!voiceBlob}});
$('voiceNoteCancel').addEventListener('click',()=>{$('voiceNoteDialog').close();resetVoiceNoteRecorder();type.value='General Note';fields()});$('voiceNoteClose').addEventListener('click',()=>{$('voiceNoteDialog').close();resetVoiceNoteRecorder();type.value='General Note';fields()});$('voiceNoteDialog').addEventListener('cancel',resetVoiceNoteRecorder);
