// Save tally entries through the form's submit event, not a competing click handler.
// This works for touch, keyboard submission and programmatic requestSubmit() alike.
function saveTallyCounterEntry(){
 const station=String($('tallyStation')?.value||'').trim();
 const first=Number($('tallyFirst')?.value);
 const standard=Number($('tallyStandard')?.value);
 const trainValue=String($('relatedTrain')?.value||'');
 const train=state.trains.find((tr,i)=>(tr.id||String(i))===trainValue);
 if(!station){status('Enter the station where the count was taken.');$('tallyStation')?.focus();return false}
 if(!train){status('Select the train from Trains Worked for this tally.');$('relatedTrain')?.focus();return false}
 if(!Number.isSafeInteger(first)||first<0||!Number.isSafeInteger(standard)||standard<0){status('Passenger counts must be whole numbers of zero or more.');return false}
 const headcode=String(train.headcode||'').trim().toUpperCase();
 const trainId=String(train.id||'');
 const trainLabel=trainReference(train);
 const selectedPortion=dyn.querySelector('input[name="passengerTrainSet"]:checked')?.value||'Whole Train';
 const trainPortion=['Front Set','Back Set','Whole Train'].includes(selectedPortion)?selectedPortion:'Whole Train';
 const id=crypto.randomUUID?crypto.randomUUID():String(Date.now())+'-'+Math.random().toString(16).slice(2);
 const entry={
  type:'Passenger Counts',
  source:'Passenger Tally Counter',
  passengerCounts:{first,standard,station,trainPortion},
  trainSets:[trainPortion],fullStanding:false,
  relatedTrainId:trainId,relatedTrainLabel:trainLabel,
  relatedTrainHeadcode:headcode,
  relatedTrainIds:trainId?[trainId]:[],
  relatedTrainHeadcodes:headcode?[headcode]:[],
  text:`First Class: ${first} · Standard Class: ${standard} · Location: ${station} · Train: ${trainLabel} · Train portion: ${trainPortion}`,
  timestamp:archiveEditingRecord?archiveTimestamp(archiveEditingRecord.shift?.date):stamp(),id
 };
 state.entries.push(entry);
 if(archiveEditingRecord){
  $('issueDialog').close();
  type.value='General Note';fields();
  $('issueDialog').querySelector('.dialoghead h2').textContent='Add log entry';
  $('entrySubmit').textContent='Add to log';
  finishArchiveEdit('Passenger tally count added to the archived daily log.');
  return true;
 }
 // Persist and verify before closing the form or showing a success message.
 if(!persist(true)){
  state.entries.pop();
  status('The passenger tally could not be saved to this device. Your counts are still on screen; please try Add to log again.');
  return false;
 }
 $('issueDialog').close();
 type.value='General Note';fields();
 $('issueDialog').querySelector('.dialoghead h2').textContent='Add log entry';
 $('entrySubmit').textContent='Add to log';
 render();
 status(`Passenger tally added to the daily Passenger Counts log for ${headcode||trainLabel} at ${station}: First Class ${first}, Standard Class ${standard}.`);
 return true;
}
let delayOtherResolver=null;
function askDelayOtherReason(){return new Promise(resolve=>{delayOtherResolver=resolve;$('delayOtherReasonInput').value='';$('delayOtherReasonDialog').showModal();$('delayOtherReasonInput').focus()})}
function finishDelayOtherReason(value){$('delayOtherReasonDialog').close();const done=delayOtherResolver;delayOtherResolver=null;if(done)done(value)}
$('delayOtherReasonSave').addEventListener('click',()=>{const v=$('delayOtherReasonInput').value.trim();if(!v){$('delayOtherReasonInput').focus();return}finishDelayOtherReason(v)});$('delayOtherReasonCancel').addEventListener('click',()=>finishDelayOtherReason(''));$('delayOtherReasonClose').addEventListener('click',()=>finishDelayOtherReason(''));
async function emailLostProperty(entry){
 const headcode=String(entry.relatedTrainHeadcode||linkedHeadcode(entry)||'HEADCODE').toUpperCase();
 const rawDate=dateDMY($('shiftDate').value||'');
 const date=rawDate.replace(/\/(\d{4})$/,(_,year)=>`/${year.slice(-2)}`);
 const subject=`lost property - ${headcode} - ${date}`;
 const body=`Hello,\n\nPlease see the lost property report below.\n\n${entryDetails(entry)}\n\nRegards`;
 const mailto=`mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
 // Copy the complete report text before opening the native email/share target.
 try{
  if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(body);
  else{const box=document.createElement('textarea');box.value=body;box.style.position='fixed';box.style.opacity='0';document.body.appendChild(box);box.select();document.execCommand('copy');box.remove()}
 }catch(err){console.warn('Could not copy lost property report text',err)}
 if(entry.photo){
  try{
   const match=String(entry.photo).match(/^data:(image\/[a-zA-Z0-9.+-]+);base64,(.+)$/);
   if(!match)throw new Error('Photo format unavailable');
   const bytes=Uint8Array.from(atob(match[2]),c=>c.charCodeAt(0));
   const ext=match[1].split('/')[1].replace('jpeg','jpg');
   const file=new File([bytes],entry.photoName||`lost-property-${headcode}.${ext}`,{type:match[1]});
   const shareData={title:subject,text:body,files:[file]};
   if(navigator.canShare&&navigator.canShare({files:[file]})&&navigator.share){await navigator.share(shareData);status('Lost property report text copied. Choose your email app to open a pre-filled email with the report and photo attached.');return}
  }catch(err){if(err?.name==='AbortError')return;console.warn('Photo sharing unavailable',err)}
  window.location.href=mailto;
  status('Lost property report text copied. Opening your email client; attach the photo from the report before sending.');
  return;
 }
 window.location.href=mailto;
 status('Lost property report copied. Opening your default email client with the subject and report populated.');
}
function createCrowdingEmail(entry){
 const headcode=String(entry.relatedTrainHeadcode||linkedHeadcode(entry)||'HEADCODE').toUpperCase();
 const rawDate=$('shiftDate')?.value||entry.timestamp||stamp();
 const date=dateDMY(rawDate);
 const shortDate=date.replace(/(\d{2})\/(\d{2})\/(\d{4})/,'$1/$2/$3').replace(/\/(\d{2})\d{2}$/,'/$1');
 const dataText=String(entry.text||'');
 const selected=FULL_STANDING_OPTIONS.filter(label=>dataText.toLowerCase().includes(label.toLowerCase()));
 const station=(dataText.match(/Last \/ current station:\s*([^\n]+)/i)||[])[1]?.trim()||'LAST/CURRENT STATION NAME';
 const lines=[];
 if(selected.includes('Reported Full  Train Full and Standing'))lines.push('full and standing throughout  (reported full train full and standing checked)');
 if(selected.includes('Standard Full and Standing'))lines.push('Standard class full and  standing  with limited space in first (standard full and standing)');
 if(selected.includes('First Class Declassified'))lines.push('First class has been declassified on this service');
 if(selected.includes('Reservation Closure Requested'))lines.push('Also, can on the day reservations be closed/suspended for this train');
 if(selected.includes('Passengers left behind at station(s)'))lines.push(`Passengers were left behind at ${station}`);
 const body=`Hello.\nCould you please show ${headcode} on ${date.replace(/\//g,' ')}\n\n${lines.join('\n\n')}\n\nThanks`;
 const subject=`${headcode} - ${shortDate} - information`;
 window.location.href=`mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
 status('Opening your default email client to create the crowding email.');
}
