function openLateBookOffEmail(entry){lateBookOffEmailEntry=entry;const related=entry.relatedTrainHeadcodes?.[0]||entry.lateBookOffHeadcode||'';const existing=String(entry.lateBookOffReason||'').trim();const trains=(state.trains||[]).filter(t=>/^\d[A-Z]\d{2}$/i.test(String(t.headcode||'')));const choice=$('lateEmailTrainChoice');choice.innerHTML='<option value="">Select a train…</option>'+trains.map(t=>{const hc=String(t.headcode).toUpperCase();return `<option value="${esc(hc)}">${esc(hc)}${t.from?' — '+esc(t.from):''}</option>`}).join('');$('lateEmailTrainChoiceWrap').classList.toggle('hidden',!!related||!trains.length);choice.value='';$('lateEmailHeadcode').value=related;$('lateEmailReason').value=existing&&LATE_BOOK_OFF_REASONS.includes(existing)?existing:(existing?'Other':'');$('lateEmailOtherReason').value=existing&&!LATE_BOOK_OFF_REASONS.includes(existing)?existing:'';$('lateEmailOtherReasonWrap').classList.toggle('hidden',$('lateEmailReason').value!=='Other');$('lateEmailMinutes').textContent=`${entry.lateBookOffMinutes||0} minutes`;$('lateBookOffEmailDialog').showModal();if(!related&&trains.length)choice.focus();else if(!related)$('lateEmailHeadcode').focus();else if(!$('lateEmailReason').value)$('lateEmailReason').focus();else if($('lateEmailReason').value==='Other')$('lateEmailOtherReason').focus();renderLateBookOffEmail()}
$('lateEmailTrainChoice').addEventListener('change',()=>{if($('lateEmailTrainChoice').value)$('lateEmailHeadcode').value=$('lateEmailTrainChoice').value;renderLateBookOffEmail()});
function renderLateBookOffEmail(){if(!lateBookOffEmailEntry)return;const hc=$('lateEmailHeadcode').value.trim().toUpperCase(),reason=selectedLateBookOffReason();$('lateEmailHeadcode').value=hc;const email=buildLateBookOffEmail(lateBookOffEmailEntry,hc||'[HEADCODE]',reason);$('lateEmailSubject').value=email.subject;$('lateEmailBody').value=email.body}
$('lateEmailHeadcode').addEventListener('input',renderLateBookOffEmail);$('lateEmailReason').addEventListener('change',updateLateBookOffOtherReason);$('lateEmailOtherReason').addEventListener('input',renderLateBookOffEmail);
$('lateBookOffEmailCancel').addEventListener('click',()=>$('lateBookOffEmailDialog').close());$('lateBookOffEmailClose').addEventListener('click',()=>$('lateBookOffEmailDialog').close());
$('lateBookOffEmailCopy').addEventListener('click',async()=>{renderLateBookOffEmail();if(!$('lateEmailHeadcode').value.trim()||!selectedLateBookOffReason()){status('Enter the headcode and select or enter a delay reason first.');return}const all=`Subject: ${$('lateEmailSubject').value}\n\n${$('lateEmailBody').value}`;try{await navigator.clipboard.writeText(all);status('Late book-off email copied, including subject and body.')}catch{const box=$('lateEmailBody');box.value=all;box.select();document.execCommand('copy');status('Late book-off email copied.')} });
$('lateBookOffEmailShare').addEventListener('click',()=>{renderLateBookOffEmail();if(!$('lateEmailHeadcode').value.trim()||!selectedLateBookOffReason()){status('Enter the headcode and select or enter a delay reason first.');return}const url=`mailto:?subject=${encodeURIComponent($('lateEmailSubject').value)}&body=${encodeURIComponent($('lateEmailBody').value)}`;window.location.href=url;});
async function saveEntryAsJpeg(entry){
 const width=1200,pad=64,contentWidth=width-pad*2,lineHeight=42;
 const title=entry.type==='Incident'?`INCIDENT — ${incidentTitle(entry)}`:String(entry.type||'LOG ENTRY').toUpperCase();
 const details=entry.type==='Photo'?`${entry.photoTitle||'PHOTO'}\n${entry.photoDescription||entry.text||''}`:entryDetails(entry);
 const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');
 const photo=entry.photo?await new Promise(resolve=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>resolve(null);img.src=entry.photo}):null;
 ctx.font='30px Arial';
 const wrap=(text,max)=>{const out=[];for(const raw of String(text??'').split('\n')){if(!raw){out.push('');continue}let line='';for(const word of raw.split(/\s+/)){const test=line?line+' '+word:word;if(ctx.measureText(test).width>max&&line){out.push(line);line=word}else line=test}out.push(line)}return out};
 const lines=wrap(details,contentWidth-36),photoHeight=photo?Math.min(620,photo.naturalHeight*(Math.min(1,(contentWidth-36)/photo.naturalWidth))):0;
 const bodyHeight=lines.length*lineHeight+ (photo?photoHeight+34:0);
 const height=270+bodyHeight+pad+58;
 canvas.width=width;canvas.height=height;
 ctx.fillStyle='#f5f2f3';ctx.fillRect(0,0,width,height);
 ctx.fillStyle='#A50034';ctx.fillRect(0,0,width,190);
 ctx.fillStyle='#fff';ctx.font='bold 30px Arial';ctx.fillText('CROSSCOUNTRY',pad,62);
 ctx.font='bold 43px Arial';let head=title;while(ctx.measureText(head).width>contentWidth&&ctx.font!=='bold 34px Arial'){ctx.font='bold 34px Arial'}ctx.fillText(head,pad,126);
 const date=fmt(entry.timestamp);ctx.font='26px Arial';ctx.fillText(date,pad,166);
 ctx.fillStyle='#fff';ctx.fillRect(pad,220,contentWidth,bodyHeight+44);
 ctx.fillStyle='#222';ctx.font='30px Arial';let y=282;
 for(const line of lines){if(line){ctx.fillText(line,pad+28,y)}y+=lineHeight}
 if(photo){const scale=Math.min(1,(contentWidth-56)/photo.naturalWidth,620/photo.naturalHeight),w=photo.naturalWidth*scale,h=photo.naturalHeight*scale;ctx.drawImage(photo,pad+28,y+8,w,h)}
 ctx.fillStyle='#6d6268';ctx.font='22px Arial';ctx.fillText('Staff Shift App · Operational log',pad,height-38);
 const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.92));if(!blob)throw new Error('JPEG export failed');
 const safe=(entry.type||'entry').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
 const filename=`${safe||'entry'}-${new Date().toISOString().slice(0,10)}.jpg`;
 const file=new File([blob],filename,{type:'image/jpeg'});
 if(navigator.canShare&&navigator.canShare({files:[file]})&&navigator.share){await navigator.share({files:[file],title:filename});status('JPEG image ready to save or share.');return}
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);status('Entry exported as a JPEG image.');
}
async function copyEntryToClipboard(entry){const heading=(entry.type==='Incident'?`INCIDENT — ${incidentTitle(entry)}`:String(entry.type||'LOG ENTRY').toUpperCase());const text=`${heading}\n${fmt(entry.timestamp)}\n\n${entryDetails(entry)}`;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text)}else{const box=document.createElement('textarea');box.value=text;box.setAttribute('readonly','');box.style.position='fixed';box.style.opacity='0';document.body.appendChild(box);box.select();const ok=document.execCommand('copy');box.remove();if(!ok)throw new Error('Clipboard copy was not available')}status('Entry copied to clipboard.')}catch(err){status('Could not copy this entry. Check clipboard permissions.')}}
