$('editEntryForm').addEventListener('submit',e=>{e.preventDefault();if(editingEntryIndex===null)return;const entry=state.entries[editingEntryIndex],newText=$('editEntryText').value.trim();if(editingIncidentUpdateIndex!==null){if(!newText){status('Incident update cannot be blank.');$('editEntryText').focus();return}const update=entry?.updates?.[editingIncidentUpdateIndex];if(!update){status('This incident update could not be found.');return}update.text=newText;update.editedAt=stamp();entry.editedAt=stamp();const parentIndex=editingIncidentUpdateParentIndex;if(archiveEditingRecord){closeEditEntry();finishArchiveEdit('Incident update amended successfully.');return}persist(true);closeEditEntry();render();const card=$('entries').querySelectorAll('.entry')[parentIndex];if(card){card.classList.add('entry-just-edited');card.scrollIntoView({behavior:'smooth',block:'center'})}status('Incident update amended. The original incident and other updates remain unchanged.');return}if(!newText){status('Entry details cannot be blank.');return}if(entry.type==='Passenger Counts'){if(!$('editRelatedTrain').value){$('editRelatedTrain').focus();status('Select the related train for these passenger counts.');return}const first=$('editPassengerFirst').value,standard=$('editPassengerStandard').value,location=$('editPassengerLocation').value.trim(),portions=[...document.querySelectorAll('input[name="editPassengerTrainSet"]:checked')].map(x=>x.value),formation=portions.length?portions:['Whole Train'],notes=$('editPassengerNotes').value.trim();if(!/^\d+$/.test(first)||!/^\d+$/.test(standard)||Number(first)<0||Number(standard)<0){status('Enter valid whole-number passenger counts.');return}if(!location){status('Enter the station or location for this count.');$('editPassengerLocation').focus();return}const oldText=String(entry.text||''),oldNote=oldText.match(/Notes(\s*\([^\n]*?\))?:/i),noteLabel=oldNote?`Notes${oldNote[1]}`:`Notes (${fmt(entry.timestamp)}${linkedHeadcode(entry)?' · '+linkedHeadcode(entry):''})`;entry.text=`First Class: ${first} · Standard Class: ${standard} · Location: ${location} · Train portion: ${formation.join(', ')}\n`+(notes?`${noteLabel}: ${notes}\n`:'');entry.trainSets=formation;entry.fullStanding=$('editPassengerStanding').checked;}else{if(!newText){status('Entry details cannot be blank.');return}entry.text=newText;}if(entry.type==='Incident'){entry.incidentName=$('editIncidentName').value.trim();entry.incidentLocation=$('editIncidentLocation').value.trim();}entry.editedAt=stamp();const selected=[...$('editRelatedTrain').selectedOptions].map(o=>state.trains[Number(o.value)]).filter(Boolean),train=selected[0]||null;entry.relatedTrainLabel=selected.map(trainReference).join(' | ');entry.relatedTrainHeadcode=train?.headcode||'';entry.relatedTrainId=train?.id||'';entry.relatedTrainIds=selected.map(x=>x.id).filter(Boolean);entry.relatedTrainHeadcodes=selected.map(x=>String(x.headcode||'').toUpperCase()).filter(Boolean);const editedIndex=editingEntryIndex;if(archiveEditingRecord){closeEditEntry();finishArchiveEdit('Archived entry updated successfully.');return}persist(true);closeEditEntry();render();const occurrenceSection=$('entries').closest('details');if(occurrenceSection)occurrenceSection.open=true;const updatedCard=$('entries').querySelectorAll('.entry')[editedIndex];if(updatedCard){updatedCard.classList.add('entry-just-edited');updatedCard.scrollIntoView({behavior:'smooth',block:'center'})}status('Changes saved and displayed in Operational Log / Occurrences.')});
