function dailyLogBwvCameraNumber(){const equipment=[...(state.entries||[])].reverse().find(e=>e&&e.type==='Shift equipment'&&/BWV\s*Cam\s*number\s*:/i.test(String(e.text||'')));if(!equipment)return '';const match=String(equipment.text||'').match(/BWV\s*Cam\s*number\s*:\s*([^\r\n]+)/i);return match?match[1].trim():'';}
function incidentActivityLabel(value){const v=String(value||'').replace(/^\W+/, '').trim().toUpperCase();if(/^(PASS|PASSING)\b/.test(v))return 'Passing';if(/^(ASST|ACC|ASSIST)\b/.test(v))return 'Assist';if(/^WORK(ING)?\b/.test(v))return 'Working';return '';}
function incidentReportAuto(entry){const train=state.trains.find(t=>(entry.relatedTrainId&&t.id===entry.relatedTrainId)||(linkedHeadcode(entry)&&String(t.headcode||'').toUpperCase()===linkedHeadcode(entry)))||null;const ts=new Date(entry.timestamp);const time=Number.isNaN(ts.getTime())?'':ts.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});const incidentDate=Number.isNaN(ts.getTime())?dateDMY($('shiftDate').value):ts.toLocaleDateString('en-GB');const updates=(entry.updates||[]).map(u=>`Update (${fmt(u.timestamp)}): ${u.text}`).join('\n\n');const saved=entry.reportDetails||{};const units=train?[train.unit,train.unit2].filter(Boolean):[];const setFormation=units.length>1?'Double set':units.length===1?'Single set':'';return {...{date:incidentDate,time,incidentLogNumber:entry.logNumber||'',activity:incidentActivityLabel(train?.from),originDestination:'',startEndLocation:'',headcode:linkedHeadcode(entry),turnNumber:$('shiftJobNumber').value.trim(),workingAlongside:'',otherInvolved:'',carriages:'',setFormation,unitNumbers:units.join(' + '),tmLocation:'',incidentTrainLocation:entry.incidentLocation||'',platform:'',journeyDirection:'',whatHappened:[String(entry.text||'').trim(),updates].filter(Boolean).join('\n\n'),personsDescription:'',witnesses:'',bwv:'',bwvCamera:dailyLogBwvCameraNumber(),serviceImpact:'',closingRemarks:'',policeAttendance:'',otherServices:''},...saved,incidentLogNumber:String(saved.incidentLogNumber||entry.logNumber||''),activity:incidentActivityLabel(saved.activity||train?.from),setFormation:String(saved.setFormation||saved.trainType||setFormation),unitNumbers:String(saved.unitNumbers||saved.formation||units.join(' + ')),bwvCamera:String(saved.bwvCamera||'').trim()||dailyLogBwvCameraNumber()};}
function openIncidentReport(entryIndex){const entry=state.entries[entryIndex];if(!entry||entry.type!=='Incident')return;incidentReportEntryIndex=entryIndex;const values=incidentReportAuto(entry);let html='',section='';incidentReportFieldDefs.forEach(f=>{if(f.section&&f.section!==section){section=f.section;html+=`<h3 class="incident-report-section">${esc(section)}</h3>`}const value=values[f.key]||'';const missing=!value;const label=`<span class="${missing?'missing-report-label':''}">${esc(f.label)}</span>`;const multiline=['whatHappened','personsDescription','witnesses','serviceImpact','closingRemarks','policeAttendance','otherServices','workingAlongside','otherInvolved'].includes(f.key);const control=f.key==='activity'?`<select name="activity"><option value="">Select activity…</option>${[['Assist','Assist (ACC or ASST)'],['Passing','Passing (PASS)'],['Working','Working']].map(([v,labelText])=>`<option value="${v}" ${value===v?'selected':''}>${labelText}</option>`).join('')}</select>`:multiline?`<textarea name="${f.key}" rows="${f.key==='whatHappened'?5:3}" placeholder="${esc(f.hint)}">${esc(value)}</textarea>`:`<input name="${f.key}" value="${esc(value)}" placeholder="${esc(f.hint)}">`;html+=`<label class="incident-report-field">${label}${control}</label>`});$('incidentReportFields').innerHTML=html;$('incidentReportDetailsDialog').showModal();}
function buildIncidentReport(entry,values){const get=k=>String(values[k]||'').trim();const lines=[];if(entry.incidentRef)lines.push(`Incident reference: ${entry.incidentRef}`);const intro=[get('date')&&`On ${get('date')}`,get('time')&&`at approximately ${get('time')}`,get('activity')&&`I was ${get('activity')==='Assist'?'assisting':get('activity')==='Passing'?'passing': 'working'}`,get('incidentLogNumber')&&`incident log / reference number ${get('incidentLogNumber')}`,get('originDestination')&&`the ${get('originDestination')}`,get('headcode')&&`with Headcode ${get('headcode')}`,get('turnNumber')&&`as part of Train Manager Turn ${get('turnNumber')}`].filter(Boolean).join(' ');if(intro)lines.push(intro+'.');const add=(heading,parts)=>{const vals=parts.filter(Boolean);if(vals.length)lines.push('',heading,...vals)};add('SERVICE AND DUTY',[get('startEndLocation')&&`I worked this train from ${get('startEndLocation')}.`,get('workingAlongside')&&`I was working alongside ${get('workingAlongside')}.`,get('otherInvolved')&&`Also involved was ${get('otherInvolved')}.`,get('carriages')&&`The train was formed of ${get('carriages')} carriages.`,get('setFormation')&&`This was a ${get('setFormation')}.`,get('unitNumbers')&&`Unit number(s): ${get('unitNumbers')}.`,get('tmLocation')&&`I was located at ${get('tmLocation')}.`,get('incidentTrainLocation')&&`At the time of the incident the train was at ${get('incidentTrainLocation')}.`,get('platform')&&`Platform ${get('platform')}.`,get('journeyDirection')&&`Travelling from ${get('journeyDirection')}.`]);add('WHAT HAPPENED?',[get('whatHappened')]);add('WHO WAS INVOLVED?',[get('personsDescription')]);add('WITNESSES',[get('witnesses')]);add('BODY WORN VIDEO',[get('bwv'),get('bwvCamera')&&`BWV camera serial number: ${get('bwvCamera')}`]);add('SERVICE IMPACT',[get('serviceImpact')]);add('CLOSING REMARKS / WHAT HAPPENED AFTER THE INCIDENT?',[get('closingRemarks')]);add('BTP / LOCAL POLICE ATTENDANCE',[get('policeAttendance')]);add('OTHER EMERGENCY SERVICES / NETWORK RAIL',[get('otherServices')]);return lines.join('\n');}
$('incidentReportDetailsForm').addEventListener('submit',e=>{e.preventDefault();if(incidentReportEntryIndex===null)return;const entry=state.entries[incidentReportEntryIndex],form=e.currentTarget,values={};incidentReportFieldDefs.forEach(f=>{values[f.key]=form.elements.namedItem(f.key)?.value?.trim()||''});entry.reportDetails=values;entry.editedAt=entry.editedAt||stamp();persist(true);const report=buildIncidentReport(entry,values);generatedIncidentReportEntryId=entry.id||entry.incidentRef||'';$('incidentReportDetailsDialog').close();$('incidentReportPreview').value=report;$('incidentReportPreviewDialog').showModal();});
