$('incidentReportSaveDaily').addEventListener('click',()=>{if(incidentReportEntryIndex===null)return;const source=state.entries[incidentReportEntryIndex];if(!source||source.type!=='Incident')return;const report=$('incidentReportPreview').value.trim();if(!report){status('There is no incident report to save.');return}let saved=state.entries.find(e=>e.type==='Incident Report'&&e.sourceIncidentId===(source.id||source.incidentRef||''));if(saved){saved.text=report;saved.editedAt=stamp();saved.relatedTrainId=source.relatedTrainId||'';saved.relatedTrainHeadcode=linkedHeadcode(source)||'';}else{saved={id:'incident-report-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),type:'Incident Report',timestamp:stamp(),text:report,sourceIncidentId:source.id||source.incidentRef||'',relatedTrainId:source.relatedTrainId||'',relatedTrainHeadcode:linkedHeadcode(source)||'',incidentRef:source.incidentRef||''};state.entries.push(saved)}persist(true);render();$('incidentReportPreviewDialog').close();const log=$('entries').closest('details');if(log)log.open=true;status(saved.editedAt?'Incident report updated in the daily log.':'Incident report saved to the daily log.');});
