function delayMinutesValue(e){if(e?.type!=='Delay')return null;const stored=e.delayMinutes;const match=String(e.text||'').match(/(?:^|\n)\s*Delay:\s*(\d+(?:\.\d+)?)\s*minutes?/i);const value=stored!==undefined&&stored!==null&&stored!==''?Number(stored):(match?Number(match[1]):NaN);return Number.isFinite(value)?value:null}
function isDelayOverTen(e){return delayMinutesValue(e)>10}
function entryLabel(e){return e.type==='Incident'?`🚨 ${incidentTitle(e)}${e.incidentRef?' · '+e.incidentRef:''}`:e.type==='Add shift pay'?'💷 Shift payment totals':({'Lost Property':'🧳 Lost Property','Defect':'🔧 Defect','Passenger Counts':'🔢 Passenger Counts','Ticket acceptance':'🎟️ Ticket acceptance','Control Message':'📟 Control Message','Delay':'⏱️ Delay','Train Diversion':'🚧 Train Diversion','Full and standing':'🛑 Full and standing','Assist':'🦮♿ Assist','Reminder':'ℹ️ Reminder','General Note':'📝 General Note','Late book off':'⌚️ Late book off','Special stop order / not to call':'🚦 Special stop order / not to call','Crew / Staffing Issue':'🪪 Crew / Staffing Issue','Photo':`📸 ${e.photoTitle||'Photo attachment'}`,'Voice note':`🎤 ${e.voiceTitle||'Voice note'}`}[e.type]||e.type)}
function commissionShiftTotals(entries){
 const rows=(entries||[]).filter(e=>e.type==='Ticket commission');let scans=0,sales=0,commission=0;
 rows.forEach(e=>{
  const t=String(e.text||'');const data=e.commission&&typeof e.commission==='object'?e.commission:{};
  const match=(patterns)=>{for(const pattern of patterns){const m=t.match(pattern);if(m)return Number(String(m[1]).replace(/,/g,''));}return null};
  const parsedScans=match([/(?:Ticket\s+)?scans?\s*:?\s*([\d,]+)/i,/(?:Shift\s+)?scans?\s*:?\s*([\d,]+)/i]);
  const parsedSales=match([/Ticket\s+sales\s*:?\s*£?\s*([\d,]+(?:\.\d{1,2})?)/i,/Sales\s*:?\s*£?\s*([\d,]+(?:\.\d{1,2})?)/i]);
  const parsedTotal=match([/(?:TOTAL\s+COMMISSION|Commission\s+for\s+shift)\s*:?\s*£?\s*([\d,]+(?:\.\d{1,2})?)/i]);
  const nScans=Number(data.scans??data.shiftScans??data.ticketScans??e.scans??parsedScans??0);
  const nSales=Number(data.sales??data.ticketSales??e.sales??parsedSales??0);
  const storedTotal=data.total??data.totalCommission??data.commission??e.totalCommission;
  let nCommission=Number(storedTotal);
  if(!Number.isFinite(nCommission)||storedTotal===undefined||storedTotal===null){
   const scanPart=Number(data.scanCommission??match([/Scan\s+commission\s*:?\s*£?\s*([\d,]+(?:\.\d{1,2})?)/i]));
   const salesPart=Number(data.salesCommission??match([/Sales\s+commission\s*:?\s*£?\s*([\d,]+(?:\.\d{1,2})?)/i]));
   if(Number.isFinite(scanPart)||Number.isFinite(salesPart))nCommission=(Number.isFinite(scanPart)?scanPart:0)+(Number.isFinite(salesPart)?salesPart:0);
   else if(parsedTotal!==null)nCommission=parsedTotal;
   else {const per=Number(data.perScan??data.commissionPerScan),pct=Number(data.salesPercent??data.salesCommissionRate);nCommission=(Number.isFinite(per)?nScans*per:0)+(Number.isFinite(pct)?nSales*pct/100:0)}
  }
  scans+=Number.isFinite(nScans)?nScans:0;sales+=Number.isFinite(nSales)?nSales:0;commission+=Number.isFinite(nCommission)?nCommission:0;
 });
 return {hasEntries:rows.length>0,scans,sales,commission};
}
function commissionReportLines(entries){const c=commissionShiftTotals(entries);return c.hasEntries?[ 'COMMISSION REPORT','-----------------',`Shift scans: ${c.scans}`,`Ticket sales: £${c.sales.toFixed(2)}`,`Commission for shift: £${c.commission.toFixed(2)}`]:[]}
function commissionDateISO(date){return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}-${String(date.getUTCDate()).padStart(2,'0')}`}
function commissionDateFromISO(value){const m=String(value||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?new Date(Date.UTC(Number(m[1]),Number(m[2])-1,Number(m[3]))):null}
function commissionAddDays(value,days){const d=commissionDateFromISO(value);if(!d)return '';d.setUTCDate(d.getUTCDate()+days);return commissionDateISO(d)}
function isCommissionPayday(value){const date=commissionDateFromISO(value),anchor=commissionDateFromISO('2026-12-18');if(!date||!anchor)return false;const days=Math.round((date-anchor)/86400000);return days%28===0}
function commissionPayPeriods(reference=nowLocal()){
 const anchor='2026-12-18',anchorDate=commissionDateFromISO(anchor),today=commissionDateFromISO(reference)||commissionDateFromISO(nowLocal());
 const dayDiff=Math.floor((today-anchorDate)/86400000);const cycles=dayDiff<0?0:Math.floor(dayDiff/28)+1;
 const paydayDate=new Date(anchorDate);paydayDate.setUTCDate(paydayDate.getUTCDate()+cycles*28);const payday=commissionDateISO(paydayDate);
 const cutoff=commissionAddDays(payday,-6),previousPayday=commissionAddDays(payday,-28),previousCutoff=commissionAddDays(previousPayday,-6);
 const currentStart=commissionAddDays(previousCutoff,1),previousPaydayBefore=commissionAddDays(previousPayday,-28),previousCutoffBefore=commissionAddDays(previousPaydayBefore,-6),previousStart=commissionAddDays(previousCutoffBefore,1);
 return {current:{start:currentStart,end:cutoff,payday},previous:{start:previousStart,end:previousCutoff,payday:previousPayday}};
}
function commissionDateLabel(value){const d=commissionDateFromISO(value);return d?d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}):value}
function commissionAllSavedEntries(){const shifts=[...state.archivedShifts];if(hasCurrentShiftData())shifts.push(currentShiftSnapshot());const seen=new Set(),out=[];shifts.forEach(record=>{const shiftDate=String(record.shift?.date||'').slice(0,10),jobNumber=String(record.shift?.jobNumber||'').trim();(record.entries||[]).filter(e=>e.type==='Ticket commission').forEach(entry=>{const key=entry.id||`${shiftDate}|${entry.timestamp||''}|${entry.text||''}`;if(seen.has(key))return;seen.add(key);out.push({entry,date:/^\d{4}-\d{2}-\d{2}$/.test(shiftDate)?shiftDate:String(entry.timestamp||'').slice(0,10),jobNumber})})});return out}
function commissionTotalsForRange(start,end){const rows=commissionAllSavedEntries().filter(row=>row.date>=start&&row.date<=end),entries=rows.map(row=>row.entry),totals=commissionShiftTotals(entries);return {...totals,entries:rows.length,shifts:new Set(rows.map(row=>row.date)).size}}
function commissionSummaryHtml(totals){return `<div class="commission-summary-grid"><div><span>Ticket scans</span><strong>${totals.scans.toLocaleString('en-GB')}</strong></div><div><span>Ticket sales</span><strong>£${totals.sales.toFixed(2)}</strong></div><div><span>Commission</span><strong class="commission-amount">£${totals.commission.toFixed(2)}</strong></div><div><span>Entries / shifts</span><strong>${totals.entries} / ${totals.shifts}</strong></div></div>${totals.hasEntries?'':'<p class="muted commission-no-records">No commission entries recorded for these dates.</p>'}`}
