function savedShiftRecordsForPay(){const records=[...state.archivedShifts];if(hasCurrentShiftData())records.push(currentShiftSnapshot());const seen=new Set(),out=[];records.forEach(record=>{const shift=record.shift||{},date=String(shift.date||'').slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return;const key=`${date}|${shift.jobNumber||''}|${shift.bookOn||''}|${shift.bookOff||''}`;if(seen.has(key))return;seen.add(key);out.push({record,date,shift})});return out}
function sundayOvertimeForRange(start,end){const rate=Number(getPayRates().sunday||0);let hours=0;const shifts=[];savedShiftRecordsForPay().forEach(item=>{if(item.date<start||item.date>end||!item.shift.bookOn||!item.shift.bookOff)return;const d=commissionDateFromISO(item.date);if(!d||d.getUTCDay()!==0)return;const [oh,om]=item.shift.bookOn.split(':').map(Number),[fh,fm]=item.shift.bookOff.split(':').map(Number);if(![oh,om,fh,fm].every(Number.isFinite))return;let minutes=fh*60+fm-(oh*60+om);if(minutes<0)minutes+=1440;if(minutes<=0||minutes>1440)return;hours+=minutes/60;shifts.push({date:item.date,hours:minutes/60,jobNumber:item.shift.jobNumber||''})});return {hours,pay:hours*rate,rate,shifts}}
function lateBookOffPayForRange(start,end){const rates=getPayRates();let pay=0,minutes=0,count=0;savedShiftRecordsForPay().forEach(item=>{if(item.date<start||item.date>end)return;const sunday=commissionDateFromISO(item.date)?.getUTCDay()===0,rate=Number(sunday?rates.sunday:rates.weekday);(item.record.entries||[]).filter(e=>e.type==='Late book off').forEach(e=>{const mins=Number(e.lateBookOffMinutes||((String(e.text||'').match(/Delay:\s*(\d+)/i)||[])[1]||0));if(Number.isFinite(mins)&&mins>0){minutes+=mins;pay+=mins/60*rate;count++}})});return {minutes,pay,count}}
function weekMondayISO(value){const d=commissionDateFromISO(value);if(!d)return '';const day=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-day);return commissionDateISO(d)}
function shiftHoursForPay(item){const shift=item.shift||{},job=String(shift.jobNumber||'').trim();if(isARShift(job)&&Number.isFinite(Number(shift.originalShiftHours))&&Number(shift.originalShiftHours)>0&&Number(shift.originalShiftHours)<=24)return Number(shift.originalShiftHours);if(/^SPARE$/i.test(job))return spareTermHours();const on=String(shift.bookOn||''),off=String(shift.bookOff||'');if(on&&off){const [oh,om]=on.split(':').map(Number),[fh,fm]=off.split(':').map(Number);if(![oh,om,fh,fm].every(Number.isFinite))return null;let minutes=fh*60+fm-(oh*60+om);if(minutes<0)minutes+=1440;if(minutes<=0||minutes>1440)return null;return minutes/60}if(isSpareOrSafetyBrief(job))return spareTermHours();return null}
function calendarCodesForDate(date){const raw=calendarCodes[date]||[];return Array.isArray(raw)?raw:(raw?[raw]:[])}
function monthlyShiftPayForRange(start,end){const rates=getPayRates(),records=savedShiftRecordsForPay();let standardHours=0,sundayHours=0,alHours=0,alSundayHours=0,alrHours=0,alrSundayHours=0,rdwHours=0,rdwSundayHours=0,sbHours=0,sbSundayHours=0,missingAL=0,missingALR=0;const counted=[];const leaveDates=Object.entries(calendarCodes).filter(([date,raw])=>date>=start&&date<=end&&(Array.isArray(raw)?raw:(raw?[raw]:[])).some(c=>c==='AL'||c==='ALR'));const leaveDateSet=new Set(leaveDates.map(([date])=>date));leaveDates.forEach(([date,raw])=>{const codes=Array.isArray(raw)?raw:(raw?[raw]:[]),saved=leaveScheduledTimes[date];if(!saved?.bookOn||!saved?.bookOff){if(codes.includes('AL'))missingAL++;if(codes.includes('ALR'))missingALR++;return}const [oh,om]=saved.bookOn.split(':').map(Number),[fh,fm]=saved.bookOff.split(':').map(Number);let minutes=fh*60+fm-(oh*60+om);if(minutes<0)minutes+=1440;if(![oh,om,fh,fm].every(Number.isFinite)||minutes<=0||minutes>1440)return;const hours=minutes/60,isSunday=commissionDateFromISO(date)?.getUTCDay()===0;if(codes.includes('AL')){if(isSunday)alSundayHours+=hours;else alHours+=hours}else if(codes.includes('ALR')){if(isSunday)alrSundayHours+=hours;else alrHours+=hours}});Object.entries(calendarCodes).forEach(([date,raw])=>{if(date<start||date>end)return;const codes=Array.isArray(raw)?raw:(raw?[raw]:[]);if(!codes.includes('SB'))return;const hours=Number(safetyBriefHours[date]);if(!Number.isFinite(hours)||hours<=0)return;if(commissionDateFromISO(date)?.getUTCDay()===0)sbSundayHours+=hours;else sbHours+=hours});records.forEach(item=>{if(item.date<start||item.date>end||leaveDateSet.has(item.date)||(Array.isArray(calendarCodes[item.date])?calendarCodes[item.date]:[calendarCodes[item.date]]).includes('SB'))return;const hours=shiftHoursForPay(item);if(hours===null)return;const isSunday=commissionDateFromISO(item.date)?.getUTCDay()===0;if(isSunday)sundayHours+=hours;else standardHours+=hours;if(item.shift.rdw){if(isSunday)rdwSundayHours+=hours;else rdwHours+=hours}counted.push(item)});const standardRate=Number(rates.weekday||0),sundayRate=Number(rates.sunday||0),standardPay=standardHours*standardRate,sundayPay=sundayHours*sundayRate,alPay=alHours*standardRate+alSundayHours*sundayRate,alrPay=alrHours*standardRate+alrSundayHours*sundayRate,rdwPay=rdwHours*standardRate+rdwSundayHours*sundayRate,sbPay=sbHours*standardRate+sbSundayHours*sundayRate;return {standardHours,sundayHours,alHours,alSundayHours,alrHours,alrSundayHours,rdwHours,rdwSundayHours,rdwPay,sbHours,sbSundayHours,sbPay,alrWeeks:0,standardRate,sundayRate,standardPay,sundayPay,alPay,alrPay,missingAL,missingALR,countedShifts:counted.length,total:standardPay+sundayPay+alPay+alrPay+sbPay}}
function grossPaySummaryHtml(start,end){const commission=commissionTotalsForRange(start,end),shifts=monthlyShiftPayForRange(start,end),late=lateBookOffPayForRange(start,end),annualLeavePay=shifts.alPay+shifts.alrPay,total=shifts.total+commission.commission+late.pay,money=n=>`£${Number(n||0).toFixed(2)}`;return `<div class="commission-summary-grid monthly-pay-grid"><div><span>Standard-rate shifts (${shifts.standardHours.toFixed(2)} hrs × ${money(shifts.standardRate)})</span><strong>${money(shifts.standardPay)}</strong></div><div><span>Sunday shifts (${shifts.sundayHours.toFixed(2)} hrs × ${money(shifts.sundayRate)})</span><strong>${money(shifts.sundayHours*shifts.sundayRate)}</strong></div><div><span>Annual leave (AL) (${(shifts.alHours+shifts.alSundayHours).toFixed(2)} hrs)</span><strong>${money(shifts.alPay)}</strong></div><div><span>Rostered annual leave (ALR) (${shifts.alrHours.toFixed(2)} hrs)</span><strong>${money(shifts.alrHours*shifts.standardRate)}</strong></div><div><span>Total annual leave pay</span><strong>${money(annualLeavePay)}</strong></div><div><span>Rest day work (RDW) (${(shifts.rdwHours+shifts.rdwSundayHours).toFixed(2)} hrs)</span><strong>${money(shifts.rdwPay)}</strong></div><div><span>🦺 Safety Brief (SB) (${(shifts.sbHours+shifts.sbSundayHours).toFixed(2)} hrs)</span><strong>${money(shifts.sbPay)}</strong></div><div><span>Ticket commission</span><strong>${money(commission.commission)}</strong></div><div><span>Late book-off / delay pay (${late.minutes} mins)</span><strong>${money(late.pay)}</strong></div><div class="monthly-pay-total"><span>Estimated gross pay</span><strong>${money(total)}</strong></div></div><p class="muted monthly-pay-note">RDW value is shown separately as a breakdown of shifts already included in standard-rate or Sunday shift pay; it is not added twice to estimated gross pay. Based on ${shifts.countedShifts} saved shift records, ${commission.entries} commission entries and ${late.count} late book-off entries. AL is only included where the original shift's Book on and Book off times have been entered; ${shifts.missingAL} AL and ${shifts.missingALR} ALR date(s) had no original shift times and were excluded. AL and ALR are included only when original Book On and Book Off times have been entered for that calendar date. Any missing shifts or incorrect input may affect this estimate. Estimate is before tax, National Insurance, pension and other deductions.</p>`}
