function commissionStatementRows(start,end){return commissionAllSavedEntries().filter(row=>row.date>=start&&row.date<=end).sort((a,b)=>a.date.localeCompare(b.date)||String(a.entry.timestamp||'').localeCompare(String(b.entry.timestamp||''))).map(row=>{const total=commissionShiftTotals([row.entry]);return {...row,scans:total.scans,sales:total.sales,commission:total.commission}})}
function exportCommissionStatement(start,end,label,payday=''){
 if(!start||!end||end<start){status('Select a valid commission statement date range first.');return}
 const rows=commissionStatementRows(start,end),totals=commissionTotalsForRange(start,end),rates=getCommissionRates();
 const money=n=>`£${Number(n||0).toFixed(2)}`,date=commissionDateLabel;
 const detailRows=rows.length?rows.map(row=>`<tr><td>${esc(date(row.date))}</td><td>${esc(row.jobNumber||'—')}</td><td class="num">${Number(row.scans||0).toLocaleString('en-GB')}</td><td class="num">${money(row.sales)}</td><td class="num">${money(row.commission)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">No commission entries recorded for this period.</td></tr>';
 const title=`Commission Statement – ${label}`;
 const html=`<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f4f7;color:#20212a;font:14px/1.5 Arial,Helvetica,sans-serif}.toolbar{display:flex;gap:10px;justify-content:flex-end;padding:12px 18px;background:#061B50}.toolbar button{border:0;border-radius:8px;padding:11px 16px;font-weight:700;cursor:pointer}.print{background:#A50034;color:#fff}.close{background:#fff;color:#061B50}.sheet{max-width:900px;margin:22px auto;padding:34px;background:#fff;box-shadow:0 3px 18px #0002}.brand{background:#061B50;color:#fff;padding:20px 22px;border-bottom:5px solid #A50034}.brand h1{font-size:21px;margin:0}.brand p{margin:3px 0 0;color:#e9eaf0}.intro{margin:22px 0}.intro h2{margin:0 0 5px;color:#A50034;font-size:20px}.meta{color:#555}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:20px 0}.metric{border:1px solid #ddd;border-radius:9px;padding:13px}.metric span{display:block;color:#666;font-size:11px;text-transform:uppercase;font-weight:700}.metric strong{display:block;font-size:22px;color:#061B50;margin-top:4px}.metric.total{border-color:#A50034;background:#fff7f9}.metric.total strong{color:#A50034}table{width:100%;border-collapse:collapse;margin-top:12px}th{background:#f0e8ec;color:#301b25;text-align:left;font-size:12px}th,td{padding:10px 9px;border:1px solid #ddd}td.num,th.num{text-align:right;font-variant-numeric:tabular-nums}.empty{text-align:center;color:#666;padding:18px}.rates{margin-top:20px;padding:12px;background:#f6f6f8;border-radius:8px;color:#555;font-size:12px}.foot{margin-top:28px;padding-top:12px;border-top:1px solid #ddd;color:#777;font-size:11px;text-align:right}@page{size:A4 portrait;margin:15mm}@media(max-width:600px){.sheet{margin:0;padding:18px}.summary{grid-template-columns:1fr}.toolbar{position:sticky;top:0}}@media print{body{background:#fff}.toolbar{display:none}.sheet{max-width:none;margin:0;padding:0;box-shadow:none}.summary{grid-template-columns:repeat(3,1fr)}tr{break-inside:avoid}thead{display:table-header-group}}</style></head><body><nav class="toolbar"><button class="close" type="button" onclick="window.close()">Close</button><button class="print" type="button" onclick="window.print()">Print / Save as PDF</button></nav><main class="sheet"><header class="brand"><h1>STAFF SHIFT APP</h1><p>Commission statement</p></header><section class="intro"><h2>${esc(title)}</h2><div class="meta"><strong>Period:</strong> ${esc(date(start))} – ${esc(date(end))}${payday?` &nbsp; · &nbsp; <strong>Payday:</strong> ${esc(date(payday))}`:''}</div></section><section class="summary"><div class="metric"><span>Ticket scans</span><strong>${Number(totals.scans||0).toLocaleString('en-GB')}</strong></div><div class="metric"><span>Ticket sales</span><strong>${money(totals.sales)}</strong></div><div class="metric total"><span>Total commission</span><strong>${money(totals.commission)}</strong></div></section><h3>Commission entries</h3><table><thead><tr><th>Date</th><th>Job / turn</th><th class="num">Scans</th><th class="num">Ticket sales</th><th class="num">Commission</th></tr></thead><tbody>${detailRows}</tbody><tfoot><tr><th colspan="2">Period total</th><th class="num">${Number(totals.scans||0).toLocaleString('en-GB')}</th><th class="num">${money(totals.sales)}</th><th class="num">${money(totals.commission)}</th></tr></tfoot></table><div class="rates">Commission rates saved in App Settings: ${money(rates.perScan)} per scan and ${Number(rates.salesPercent||0)}% of ticket sales. Statement generated from commission entries saved in active and archived shifts.</div><p class="foot">Generated ${esc(new Date().toLocaleString('en-GB'))} · Staff Shift App ${VERSION}</p></main></body></html>`;
 const w=window.open('','_blank');if(!w){status('Allow pop-ups to open the commission statement, then choose Print / Save as PDF.');return}w.document.open();w.document.write(html);w.document.close();status('Commission statement opened. Choose Print / Save as PDF to create your PDF.');
}
