function report(){
 const s=snapshot();
 const divider='────────────────────────────────────────';
 const lines=[
  'XC SHIFTAPP | OPERATIONAL SHIFT LOG',divider,
  `DATE          ${dateDMY(s.shift.date)}`,
  ...(s.shift.jobNumber?[`JOB NUMBER    ${s.shift.jobNumber}`]:[]),...(s.shift.bookOn?[`BOOK ON       ${s.shift.bookOn}`]:[]),...(s.shift.bookOff?[`BOOK OFF      ${s.shift.bookOff}`]:[]),...(s.shift.bookOn&&s.shift.bookOff?[`SHIFT LENGTH  ${shiftLengthText(s.shift.bookOn,s.shift.bookOff)}`]:[]),  ...(s.shift.notes?['','SHIFT NOTES',s.shift.notes]:[]),
  ...(commissionReportLines(s.entries).length?['',...commissionReportLines(s.entries)]:[]),
  '',divider,'TRAINS',divider,
  ...(s.trains.length?s.trains.map((t,i)=>`${i+1}. ${[t.from,t.headcode].filter(Boolean).join('  |  ')}${/(PASS|TAXI)/i.test(t.from||'')?[t.routeFrom&&`\n   From: ${t.routeFrom}`,t.routeTo&&`\n   To: ${t.routeTo}`].filter(Boolean).join(''):needsUnit(t.from)?(t.unit?`\n   Unit: ${t.unit}${t.unit2?' + '+t.unit2:''}`:''):''}`):['No trains recorded']),
  '',divider,'OPERATIONAL LOG / OCCURRENCES',divider,
  ...(s.entries.length?groupedEntries(s.entries).map((item,i)=>item.kind==='defectGroup'?`${String(i+1).padStart(2,'0')}  ${defectGroupPlain(item)}`:item.kind==='passengerGroup'?`${String(i+1).padStart(2,'0')}  ${passengerGroupPlain(item)}`:`${String(i+1).padStart(2,'0')}  ${entryLabel(item.entry)}\n     ${fmt(item.entry.timestamp)}\n${reportLines(entryDetails(item.entry)).map(x=>'     '+x).join('\n')}`):['No entries recorded']),
  '',divider,`Generated by Staff Shift App ${VERSION}`
 ];
 return lines.join('\n');
}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text)}else{fallbackCopy(text)}status('Formatted shift log copied to clipboard.')}catch(err){try{fallbackCopy(text);status('Formatted shift log copied to clipboard.')}catch(e){status('Copy unavailable. Please use a secure browser connection.')}}}
function fallbackCopy(text){const el=document.createElement('textarea');el.value=text;el.setAttribute('readonly','');el.style.position='fixed';el.style.opacity='0';document.body.appendChild(el);el.select();const ok=document.execCommand('copy');el.remove();if(!ok)throw new Error('Clipboard copy failed')}
