async function saveArchivedShiftAsJpeg(record){
 const shift=record.shift||{},trains=Array.isArray(record.trains)?record.trains:[],entries=Array.isArray(record.entries)?record.entries:[],W=1200,P=64,inner=W-P*2,lines=[];let y=0;
 const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=W;canvas.height=1000;
 const wrap=(text,max,font='25px Arial')=>{ctx.font=font;const out=[];for(const raw of String(text??'').split('\n')){if(!raw){out.push('');continue}let line='';for(const word of raw.split(/\s+/)){const test=line?line+' '+word:word;if(ctx.measureText(test).width>max&&line){out.push(line);line=word}else line=test}out.push(line)}return out};
 const addText=(text,font='25px Arial',color='#292329',gap=12)=>{const ls=wrap(text,inner-40,font);ctx.font=font;lines.push({kind:'text',lines:ls,font,color,gap});};
 const addImage=async data=>{if(!data)return;const img=await new Promise(resolve=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>resolve(null);im.src=data});if(img){const scale=Math.min(1,(inner-60)/img.naturalWidth,900/img.naturalHeight);lines.push({kind:'image',img,w:img.naturalWidth*scale,h:img.naturalHeight*scale})}};
 addText('CROSSCOUNTRY','bold 30px Arial','#A50034',8);addText('SHIFT RECORD','bold 48px Arial','#A50034',14);addText(`Date: ${dateDMY(shift.date)}    Job number: ${shift.jobNumber||'—'}`,'bold 28px Arial','#292329',10);if(shift.bookOn||shift.bookOff)addText(`Book on: ${shift.bookOn||'—'}    Book off: ${shift.bookOff||'—'}${shift.bookOn&&shift.bookOff?'    Length: '+shiftLengthText(shift.bookOn,shift.bookOff):''}`);if(shift.notes)addText(`Shift notes:\n${shift.notes}`);addText('TRAINS','bold 30px Arial','#A50034',8);if(trains.length)trains.forEach(t=>addText(`${t.headcode||'No headcode'} — ${t.from||'Working'}${needsUnit(t.from)?' · Unit '+(t.unit||'—')+(t.unit2?' + '+t.unit2:''):''}${/(PASS|TAXI)/i.test(t.from||'')?' · '+(t.routeFrom||'—')+' → '+(t.routeTo||'—'):''}`));else addText('No trains recorded.');addText('OPERATIONAL LOG / OCCURRENCES','bold 30px Arial','#A50034',8);if(entries.length){for(const e of entries){addText(`${entryLabel(e)} · ${fmt(e.timestamp)}`,'bold 26px Arial','#A50034',5);addText(e.type==='Photo'?`${e.photoTitle||'Photo'}\n${e.photoDescription||e.text||''}`:entryDetails(e),'24px Arial','#292329',8);if(e.photo)await addImage(e.photo);if(Array.isArray(e.updates))for(const u of e.updates)addText(`UPDATE · ${fmt(u.timestamp)}\n${u.text||''}`,'22px Arial','#51464d',8)}}else addText('No log entries recorded.');
 let total=180;for(const block of lines){if(block.kind==='text')total+=block.lines.length*36+block.gap+24;else total+=block.h+24}total+=80;const full=document.createElement('canvas');full.width=W;full.height=total;const c=full.getContext('2d');c.fillStyle='#f5f2f3';c.fillRect(0,0,W,total);c.fillStyle='#A50034';c.fillRect(0,0,W,150);c.fillStyle='#fff';c.font='bold 30px Arial';c.fillText('CROSSCOUNTRY',P,55);c.font='bold 43px Arial';c.fillText('SHIFT RECORD',P,112);let yy=190;c.fillStyle='#fff';c.fillRect(P,yy-20,inner,total-yy-35);yy+=20;
 for(const b of lines){if(b.kind==='text'){c.font=b.font;c.fillStyle=b.color;for(const line of b.lines){if(line)c.fillText(line,P+24,yy);yy+=36}yy+=b.gap+12}else{c.drawImage(b.img,P+24,yy,b.w,b.h);yy+=b.h+24}}
 c.fillStyle='#6d6268';c.font='18px Arial';c.fillText(`Staff Shift App · ${dateDMY(shift.date)} · ${shift.jobNumber||'Shift'} · Exported ${new Date().toLocaleString('en-GB')}`,P,total-28);
 const maxPage=5000,files=[];for(let top=0,n=1;top<total;top+=maxPage,n++){const h=Math.min(maxPage,total-top),page=document.createElement('canvas');page.width=W;page.height=h;page.getContext('2d').drawImage(full,0,top,W,h,0,0,W,h);const blob=await new Promise(resolve=>page.toBlob(resolve,'image/jpeg',.9));if(!blob)throw new Error('JPEG page could not be created');const safe=String(shift.jobNumber||'shift').replace(/[^a-z0-9-]/gi,'-');files.push(new File([blob],`XC-Shift-${dateDMY(shift.date).replaceAll('/','-')}-${safe}-page-${n}.jpg`,{type:'image/jpeg'}))}
 if(navigator.canShare&&navigator.canShare({files})&&navigator.share){await navigator.share({files,title:'Archived shift JPEG export'});status(`Archived shift exported as ${files.length} JPEG page(s).`)}else{for(const file of files){const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}status(`Archived shift exported as ${files.length} JPEG page(s).`)}
}
